__CR('t:code',[{"t":"문자열 다루기","l":[{"t":"문자열 기본 변환","q":[{"t":"code","run":"js","k":"jsb-capitalize","q":"문자열의 첫 글자만 대문자로, 나머지는 소문자로 바꾸는 capitalize 함수를 작성하세요. 빈 문자열은 빈 문자열을 반환합니다.","src":"function capitalize(s){\n  // TODO\n  \n}","tests":[{"in":"capitalize(\"hello\")","out":"\"Hello\""},{"in":"capitalize(\"WORLD\")","out":"\"World\""},{"in":"capitalize(\"javaScript\")","out":"\"Javascript\""},{"in":"capitalize(\"a\")","out":"\"A\""}],"edge":[{"in":"capitalize(\"\")","out":"\"\""}],"ex":"첫 글자는 toUpperCase, slice(1)로 자른 나머지는 toLowerCase 처리한 뒤 이어붙입니다.\n💡 개념: 문자열은 불변이라 slice로 잘라 새 문자열을 만듭니다.\n🛠 실무: 이름·제목 표시를 일관된 형식으로 정규화할 때 자주 씁니다."},{"t":"code","run":"js","k":"jsb-count-vowels","q":"문자열에 포함된 모음(a, e, i, o, u)의 개수를 대소문자 구분 없이 세는 countVowels 함수를 작성하세요.","src":"function countVowels(s){\n  // TODO\n  \n}","tests":[{"in":"countVowels(\"hello\")","out":"2"},{"in":"countVowels(\"sky\")","out":"0"},{"in":"countVowels(\"AEIOU\")","out":"5"},{"in":"countVowels(\"JavaScript\")","out":"3"}],"edge":[{"in":"countVowels(\"\")","out":"0"}],"ex":"소문자로 변환한 뒤 각 글자가 'aeiou'에 포함되는지 검사하며 셉니다.\n💡 개념: for...of는 문자열을 글자 단위로 순회합니다.\n🛠 실무: 간단한 텍스트 통계·검증 로직의 기초 패턴입니다."},{"t":"code","run":"js","k":"jsb-is-anagram","q":"두 문자열이 서로 애너그램(같은 글자들의 재배열)인지 판별하는 isAnagram 함수를 작성하세요. true 또는 false를 반환합니다.","src":"function isAnagram(a, b){\n  // TODO\n  \n}","tests":[{"in":"isAnagram(\"listen\",\"silent\")","out":"true"},{"in":"isAnagram(\"hello\",\"world\")","out":"false"},{"in":"isAnagram(\"abc\",\"cab\")","out":"true"},{"in":"isAnagram(\"aab\",\"abb\")","out":"false"}],"edge":[{"in":"isAnagram(\"\",\"\")","out":"true"}],"ex":"두 문자열을 각각 정렬해 이어붙인 결과가 같은지 비교합니다.\n💡 개념: split('').sort().join('')은 글자 정렬의 관용구입니다.\n🛠 실무: 중복 데이터 판별, 퍼즐·게임 로직에 응용됩니다."}],"th":{"sum":"**문자열 변환·가공** 실습. 대소문자·모음 세기·애너그램·자르기·단어 세기·케이스 변환의 구현 패턴과 빈 문자열 엣지케이스를 익힌다.","body":[{"h":"기본 변환","t":"capitalize는 첫 글자만 대문자, 나머지는 소문자로 만들되 빈 문자열은 그대로 반환한다. 모음 세기는 대소문자를 통일한 뒤 집합 `{a,e,i,o,u}` 포함 여부로 카운트. 애너그램은 정렬 후 비교하거나 글자별 빈도 맵이 같은지 확인한다."},{"h":"가공과 분해","t":"truncate는 길이가 n보다 클 때만 앞 n글자에 '...'을 붙인다(n 이하면 원본). 단어 세기는 `split()`으로 연속·양끝 공백을 제거해야 하며, 빈/공백 문자열은 0. camelCase→snake_case는 대문자 앞에 밑줄을 넣고 소문자로 바꾼다. 이니셜은 각 단어 첫 글자를 대문자로 모은다."}],"code":{"c":"function capitalize(s) {\n  if (s.length === 0) return \"\";\n  return s[0].toUpperCase() + s.slice(1).toLowerCase();\n}\n\nfunction isAnagram(a, b) {\n  const key = x => [...x].sort().join(\"\");\n  return key(a) === key(b);\n}","cap":"빈 문자열 방어, 애너그램은 정렬 후 비교."},"key":["빈 문자열은 항상 먼저 방어 처리","애너그램 = 정렬 결과 또는 빈도 맵 일치","단어 세기는 split()으로 연속 공백 정리 후 0 처리","camelCase→snake_case: 대문자 앞 '_' + 소문자화"]}},{"t":"문자열 가공과 분해","q":[{"t":"code","run":"js","k":"jsb-truncate","q":"문자열 길이가 n보다 크면 앞에서 n글자만 남기고 '...'을 붙여 반환하는 truncate(s, n) 함수를 작성하세요. n 이하이면 원본을 그대로 반환합니다.","src":"function truncate(s, n){\n  // TODO\n  \n}","tests":[{"in":"truncate(\"hello world\", 5)","out":"\"hello...\""},{"in":"truncate(\"hi\", 5)","out":"\"hi\""},{"in":"truncate(\"exactly\", 7)","out":"\"exactly\""},{"in":"truncate(\"abcdef\", 3)","out":"\"abc...\""}],"edge":[{"in":"truncate(\"\", 3)","out":"\"\""}],"ex":"길이가 n을 초과할 때만 slice(0, n)에 '...'을 붙이고, 아니면 원본을 반환합니다.\n💡 개념: 경계 조건(정확히 n일 때)을 명확히 정의하는 것이 중요합니다.\n🛠 실무: 목록·카드 UI에서 긴 텍스트를 줄일 때 쓰는 전형적 헬퍼입니다."},{"t":"code","run":"js","k":"jsb-word-count","q":"공백으로 구분된 단어의 개수를 세는 wordCount 함수를 작성하세요. 앞뒤·중간의 연속 공백은 무시하고, 빈 문자열이나 공백만 있으면 0을 반환합니다.","src":"function wordCount(s){\n  // TODO\n  \n}","tests":[{"in":"wordCount(\"hello world\")","out":"2"},{"in":"wordCount(\"  one  two   three \")","out":"3"},{"in":"wordCount(\"single\")","out":"1"}],"edge":[{"in":"wordCount(\"\")","out":"0"},{"in":"wordCount(\"   \")","out":"0"}],"ex":"trim으로 양끝 공백을 제거하고, 빈 문자열이면 0, 아니면 정규식 /\\s+/로 나눈 배열의 길이를 반환합니다.\n💡 개념: 연속 공백을 하나로 취급하려면 split(/\\s+/)를 씁니다.\n🛠 실무: 입력 검증, 글자수·단어수 표시 기능의 기본입니다."},{"t":"code","run":"js","k":"jsb-to-snake-case","q":"camelCase 문자열을 snake_case로 바꾸는 toSnakeCase 함수를 작성하세요. 대문자는 앞에 밑줄을 붙이고 소문자로 바꿉니다.","src":"function toSnakeCase(s){\n  // TODO\n  \n}","tests":[{"in":"toSnakeCase(\"helloWorld\")","out":"\"hello_world\""},{"in":"toSnakeCase(\"myVariableName\")","out":"\"my_variable_name\""},{"in":"toSnakeCase(\"hello\")","out":"\"hello\""},{"in":"toSnakeCase(\"userID\")","out":"\"user_i_d\""}],"edge":[{"in":"toSnakeCase(\"\")","out":"\"\""}],"ex":"replace와 정규식 /[A-Z]/g로 모든 대문자를 찾아 '_' + 소문자로 치환합니다.\n💡 개념: replace의 콜백은 매칭된 문자열을 인자로 받습니다.\n🛠 실무: API 필드명 규칙(카멜↔스네이크) 변환에 자주 필요합니다."},{"t":"code","run":"js","k":"jsb-initials","q":"여러 단어로 된 이름에서 각 단어의 첫 글자를 대문자로 모아 이니셜을 만드는 initials 함수를 작성하세요. 빈 문자열은 빈 문자열을 반환합니다.","src":"function initials(s){\n  // TODO\n  \n}","tests":[{"in":"initials(\"john doe\")","out":"\"JD\""},{"in":"initials(\"mary jane watson\")","out":"\"MJW\""},{"in":"initials(\"alice\")","out":"\"A\""}],"edge":[{"in":"initials(\"\")","out":"\"\""},{"in":"initials(\"  bob  smith \")","out":"\"BS\""}],"ex":"trim 후 /\\s+/로 단어를 나누고, 각 단어의 첫 글자를 대문자로 모아 이어붙입니다.\n💡 개념: map으로 변환하고 join('')으로 합치는 조합입니다.\n🛠 실무: 아바타 이니셜 표시 등 UI에서 흔히 쓰입니다."},{"t":"code","run":"js","k":"jsb-reverse-words","q":"문장의 단어 순서를 뒤집는 reverseWords 함수를 작성하세요. 단어는 공백으로 구분하며, 결과는 단어 사이에 공백 하나로 이어붙입니다.","src":"function reverseWords(s){\n  // TODO\n  \n}","tests":[{"in":"reverseWords(\"hello world foo\")","out":"\"foo world hello\""},{"in":"reverseWords(\"one two\")","out":"\"two one\""},{"in":"reverseWords(\"single\")","out":"\"single\""}],"edge":[{"in":"reverseWords(\"\")","out":"\"\""}],"ex":"trim 후 /\\s+/로 나눈 배열을 reverse하고 공백으로 join합니다.\n💡 개념: 배열의 reverse는 원본을 뒤집어 반환합니다.\n🛠 실무: 텍스트 처리·간단한 파싱 로직에서 응용됩니다."}],"th":{"sum":"**문자열 변환·가공** 실습. 대소문자·모음 세기·애너그램·자르기·단어 세기·케이스 변환의 구현 패턴과 빈 문자열 엣지케이스를 익힌다.","body":[{"h":"가공과 분해","t":"truncate는 길이가 n보다 클 때만 앞 n글자에 '...'을 붙인다(n 이하면 원본). 단어 세기는 `split()`으로 연속·양끝 공백을 제거해야 하며, 빈/공백 문자열은 0. camelCase→snake_case는 대문자 앞에 밑줄을 넣고 소문자로 바꾼다. 이니셜은 각 단어 첫 글자를 대문자로 모은다."},{"h":"기본 변환","t":"capitalize는 첫 글자만 대문자, 나머지는 소문자로 만들되 빈 문자열은 그대로 반환한다. 모음 세기는 대소문자를 통일한 뒤 집합 `{a,e,i,o,u}` 포함 여부로 카운트. 애너그램은 정렬 후 비교하거나 글자별 빈도 맵이 같은지 확인한다."}],"code":{"c":"function capitalize(s) {\n  if (s.length === 0) return \"\";\n  return s[0].toUpperCase() + s.slice(1).toLowerCase();\n}\n\nfunction isAnagram(a, b) {\n  const key = x => [...x].sort().join(\"\");\n  return key(a) === key(b);\n}","cap":"빈 문자열 방어, 애너그램은 정렬 후 비교."},"key":["빈 문자열은 항상 먼저 방어 처리","애너그램 = 정렬 결과 또는 빈도 맵 일치","단어 세기는 split()으로 연속 공백 정리 후 0 처리","camelCase→snake_case: 대문자 앞 '_' + 소문자화"]}}]},{"t":"배열 다루기","l":[{"t":"배열 집계와 변형","q":[{"t":"code","run":"js","k":"jsb-sum-even","q":"숫자 배열에서 짝수만 골라 합을 구하는 sumEven 함수를 작성하세요. 짝수가 없으면 0을 반환합니다.","src":"function sumEven(arr){\n  // TODO\n  \n}","tests":[{"in":"sumEven([1,2,3,4])","out":"6"},{"in":"sumEven([2,4,6])","out":"12"},{"in":"sumEven([1,3,5])","out":"0"},{"in":"sumEven([0,10,-4])","out":"6"}],"edge":[{"in":"sumEven([])","out":"0"}],"ex":"filter로 짝수(x%2===0)만 남기고 reduce로 합산합니다. 초기값 0을 주면 빈 배열도 안전합니다.\n💡 개념: filter와 reduce를 조합한 대표적 함수형 패턴입니다.\n🛠 실무: 조건에 맞는 데이터만 집계하는 리포트 로직의 기본입니다."},{"t":"code","run":"js","k":"jsb-flatten1","q":"중첩 배열을 한 단계만 평탄화하는 flatten1 함수를 작성하세요. 두 단계 이상 중첩된 요소는 그대로 둡니다.","src":"function flatten1(arr){\n  // TODO\n  \n}","tests":[{"in":"flatten1([[1,2],[3,4]])","out":"[1,2,3,4]"},{"in":"flatten1([[1],[2,3],[4]])","out":"[1,2,3,4]"},{"in":"flatten1([[1,[2]],[3]])","out":"[1,[2],3]"}],"edge":[{"in":"flatten1([])","out":"[]"}],"ex":"reduce에서 각 요소를 concat으로 이어붙이면 한 단계만 펼쳐집니다.\n💡 개념: concat은 배열 인자를 한 겹 벗겨서 합칩니다. (arr.flat(1)과 동일)\n🛠 실무: 페이지별로 나눠 받은 결과 배열을 합칠 때 유용합니다."},{"t":"code","run":"js","k":"jsb-chunk","q":"배열을 크기 n의 덩어리들로 나누는 chunk(arr, n) 함수를 작성하세요. 마지막 덩어리는 n보다 작을 수 있습니다.","src":"function chunk(arr, n){\n  // TODO\n  \n}","tests":[{"in":"chunk([1,2,3,4,5], 2)","out":"[[1,2],[3,4],[5]]"},{"in":"chunk([1,2,3,4], 2)","out":"[[1,2],[3,4]]"},{"in":"chunk([1,2,3], 1)","out":"[[1],[2],[3]]"},{"in":"chunk([1,2,3], 5)","out":"[[1,2,3]]"}],"edge":[{"in":"chunk([], 2)","out":"[]"}],"ex":"i를 n씩 증가시키며 slice(i, i+n)으로 잘라 결과에 담습니다.\n💡 개념: slice는 범위를 벗어나도 안전하게 있는 만큼만 반환합니다.\n🛠 실무: 페이지네이션, 배치 처리 단위로 데이터를 쪼갤 때 씁니다."}],"th":{"sum":"**배열 집계·변형** 실습. 짝수 합·1단계 평탄화·청크·중복 제거·회전·교집합·최대차의 구현과 경계 조건을 다룬다.","body":[{"h":"집계와 변형","t":"짝수 합은 `x % 2 === 0` 필터 후 합(없으면 0). 1단계 평탄화는 요소가 배열이면 펼치고 아니면 그대로 둔다(깊은 중첩은 유지). 청크는 n개씩 잘라 마지막은 n보다 작을 수 있다. 최대차는 max-min이며 원소 1개면 0."},{"h":"집합과 순서","t":"순서 유지 중복 제거는 `Set`으로 '본 값'을 추적하며 처음 것만 남긴다. 왼쪽 n칸 회전은 `n % len`으로 정규화해 길이보다 큰 n도 처리한다. 교집합은 두 번째 배열을 Set으로 만들고 첫 배열 순서대로, 중복 없이 담는다."}],"code":{"c":"function rotate(arr, n) {\n  const len = arr.length;\n  if (len === 0) return [];\n  const k = ((n % len) + len) % len;  // 큰 n·음수 방어\n  return arr.slice(k).concat(arr.slice(0, k));\n}\n\nfunction chunk(arr, n) {\n  const res = [];\n  for (let i = 0; i < arr.length; i += n) res.push(arr.slice(i, i + n));\n  return res;\n}","cap":"회전은 n % len으로 정규화, 청크 마지막은 짧을 수 있음."},"key":["회전은 n % len로 정규화(큰 n 방어)","순서 유지 중복 제거는 Set으로 '본 값' 추적","교집합은 Set 조회 + 첫 배열 순서·중복 제거","빈 배열·단일 원소 경계 먼저 처리"]}},{"t":"집합과 순서 다루기","q":[{"t":"code","run":"js","k":"jsb-unique","q":"배열에서 중복을 제거하되 처음 나타난 순서를 유지하는 unique 함수를 작성하세요.","src":"function unique(arr){\n  // TODO\n  \n}","tests":[{"in":"unique([1,2,2,3,1])","out":"[1,2,3]"},{"in":"unique([1,1,1])","out":"[1]"},{"in":"unique([1,2,3])","out":"[1,2,3]"},{"in":"unique([3,1,3,2,1])","out":"[3,1,2]"}],"edge":[{"in":"unique([])","out":"[]"}],"ex":"Set은 중복을 자동 제거하고 삽입 순서를 유지하므로 [...new Set(arr)]로 간단히 해결됩니다.\n💡 개념: Set은 값의 유일성을 보장하는 자료구조입니다.\n🛠 실무: 태그·아이디 목록 중복 정리에 흔히 쓰입니다."},{"t":"code","run":"js","k":"jsb-rotate","q":"배열을 왼쪽으로 n칸 회전하는 rotate(arr, n) 함수를 작성하세요. n이 배열 길이보다 커도 정상 동작해야 합니다.","src":"function rotate(arr, n){\n  // TODO\n  \n}","tests":[{"in":"rotate([1,2,3,4,5], 2)","out":"[3,4,5,1,2]"},{"in":"rotate([1,2,3], 1)","out":"[2,3,1]"},{"in":"rotate([1,2,3], 0)","out":"[1,2,3]"},{"in":"rotate([1,2,3], 4)","out":"[2,3,1]"}],"edge":[{"in":"rotate([], 2)","out":"[]"}],"ex":"n을 길이로 나눈 나머지 k를 구해 slice(k)와 slice(0,k)를 이어붙입니다.\n💡 개념: 모듈로 연산으로 큰 회전량을 실제 유효 범위로 줄입니다.\n🛠 실무: 캐러셀·순환 큐 구현의 핵심 아이디어입니다."},{"t":"code","run":"js","k":"jsb-intersection","q":"두 배열의 공통 원소를 첫 배열의 순서대로, 중복 없이 반환하는 intersection(a, b) 함수를 작성하세요.","src":"function intersection(a, b){\n  // TODO\n  \n}","tests":[{"in":"intersection([1,2,3],[2,3,4])","out":"[2,3]"},{"in":"intersection([1,2],[3,4])","out":"[]"},{"in":"intersection([1,2,2,3],[2,3])","out":"[2,3]"},{"in":"intersection([5,1,2],[2,5])","out":"[5,2]"}],"edge":[{"in":"intersection([],[1])","out":"[]"}],"ex":"b를 Set으로 만들어 조회를 빠르게 하고, a의 중복을 제거한 뒤 b에 있는 값만 남깁니다.\n💡 개념: Set의 has는 평균 O(1) 조회를 제공합니다.\n🛠 실무: 권한·태그 교집합 계산 등에 쓰입니다."},{"t":"code","run":"js","k":"jsb-max-diff","q":"배열의 최댓값과 최솟값의 차이를 구하는 maxDiff 함수를 작성하세요. 원소가 하나면 0을 반환합니다.","src":"function maxDiff(arr){\n  // TODO\n  \n}","tests":[{"in":"maxDiff([1,5,3,9,2])","out":"8"},{"in":"maxDiff([4,4,4])","out":"0"},{"in":"maxDiff([-3,7])","out":"10"}],"edge":[{"in":"maxDiff([5])","out":"0"}],"ex":"Math.max와 Math.min에 스프레드로 배열을 펼쳐 넣고 그 차이를 반환합니다.\n💡 개념: Math.max(...arr)는 배열을 개별 인자로 전개해 전달합니다.\n🛠 실무: 데이터 범위(레인지) 계산의 기본 형태입니다."}],"th":{"sum":"**배열 집계·변형** 실습. 짝수 합·1단계 평탄화·청크·중복 제거·회전·교집합·최대차의 구현과 경계 조건을 다룬다.","body":[{"h":"집합과 순서","t":"순서 유지 중복 제거는 `Set`으로 '본 값'을 추적하며 처음 것만 남긴다. 왼쪽 n칸 회전은 `n % len`으로 정규화해 길이보다 큰 n도 처리한다. 교집합은 두 번째 배열을 Set으로 만들고 첫 배열 순서대로, 중복 없이 담는다."},{"h":"집계와 변형","t":"짝수 합은 `x % 2 === 0` 필터 후 합(없으면 0). 1단계 평탄화는 요소가 배열이면 펼치고 아니면 그대로 둔다(깊은 중첩은 유지). 청크는 n개씩 잘라 마지막은 n보다 작을 수 있다. 최대차는 max-min이며 원소 1개면 0."}],"code":{"c":"function rotate(arr, n) {\n  const len = arr.length;\n  if (len === 0) return [];\n  const k = ((n % len) + len) % len;  // 큰 n·음수 방어\n  return arr.slice(k).concat(arr.slice(0, k));\n}\n\nfunction chunk(arr, n) {\n  const res = [];\n  for (let i = 0; i < arr.length; i += n) res.push(arr.slice(i, i + n));\n  return res;\n}","cap":"회전은 n % len으로 정규화, 청크 마지막은 짧을 수 있음."},"key":["회전은 n % len로 정규화(큰 n 방어)","순서 유지 중복 제거는 Set으로 '본 값' 추적","교집합은 Set 조회 + 첫 배열 순서·중복 제거","빈 배열·단일 원소 경계 먼저 처리"]}}]},{"t":"객체·자료 변환","l":[{"t":"객체 선택과 뒤집기","q":[{"t":"code","run":"js","k":"jsb-pick","q":"객체에서 주어진 키 목록에 해당하는 속성만 골라 새 객체로 반환하는 pick(obj, keys) 함수를 작성하세요. 존재하지 않는 키는 무시합니다.","src":"function pick(obj, keys){\n  // TODO\n  \n}","tests":[{"in":"pick({a:1,b:2,c:3}, [\"a\",\"c\"])","out":"{\"a\":1,\"c\":3}"},{"in":"pick({a:1,b:2}, [\"b\"])","out":"{\"b\":2}"},{"in":"pick({a:1}, [\"x\"])","out":"{}"}],"edge":[{"in":"pick({}, [\"a\"])","out":"{}"}],"ex":"키 목록을 순회하며 객체에 실제로 존재하는 키만 새 객체에 복사합니다.\n💡 개념: hasOwnProperty로 상속 속성이 아닌 자기 속성만 확인합니다.\n🛠 실무: API 응답에서 필요한 필드만 추려 내보낼 때 씁니다."},{"t":"code","run":"js","k":"jsb-invert","q":"객체의 키와 값을 서로 뒤집는 invert 함수를 작성하세요. 기존 값이 새 키가 되고, 기존 키가 새 값이 됩니다.","src":"function invert(obj){\n  // TODO\n  \n}","tests":[{"in":"invert({a:1,b:2})","out":"{\"1\":\"a\",\"2\":\"b\"}"},{"in":"invert({x:\"y\"})","out":"{\"y\":\"x\"}"},{"in":"invert({name:\"kim\",role:\"dev\"})","out":"{\"kim\":\"name\",\"dev\":\"role\"}"}],"edge":[{"in":"invert({})","out":"{}"}],"ex":"for...in으로 키를 순회하며 r[obj[k]]=k 형태로 값과 키를 뒤집습니다.\n💡 개념: 객체 키는 항상 문자열이라 숫자 값도 문자열 키가 됩니다.\n🛠 실무: 코드↔라벨 매핑을 양방향으로 만들 때 유용합니다."},{"t":"code","run":"js","k":"jsb-key-by-first","q":"단어 배열을 각 단어의 첫 글자를 키로 하는 객체로 만드는 keyByFirst 함수를 작성하세요. 같은 첫 글자가 있으면 나중 단어가 값을 덮어씁니다.","src":"function keyByFirst(words){\n  // TODO\n  \n}","tests":[{"in":"keyByFirst([\"apple\",\"avocado\",\"banana\"])","out":"{\"a\":\"avocado\",\"b\":\"banana\"}"},{"in":"keyByFirst([\"cat\"])","out":"{\"c\":\"cat\"}"},{"in":"keyByFirst([\"dog\",\"deer\",\"cow\"])","out":"{\"d\":\"deer\",\"c\":\"cow\"}"}],"edge":[{"in":"keyByFirst([])","out":"{}"}],"ex":"각 단어의 첫 글자 w[0]를 키로 삼아 객체에 할당하면, 같은 키는 자연히 마지막 값으로 덮입니다.\n💡 개념: 객체 할당은 기존 키를 갱신합니다.\n🛠 실무: 리스트를 특정 기준으로 인덱싱(keyBy)하는 흔한 패턴입니다."}],"th":{"sum":"**객체 변환** 실습. 키 선택(pick)·키-값 뒤집기·그룹핑·카운트 병합·값 합계·중첩 경로 검사를 구현한다.","body":[{"h":"선택과 뒤집기","t":"pick은 주어진 키 목록 중 존재하는 것만 새 객체로 담는다(없는 키 무시). invert는 값을 새 키로, 키를 새 값으로 뒤집는다. keyByFirst는 첫 글자를 키로 하되 같은 첫 글자면 나중 단어가 덮어쓴다."},{"h":"집계와 경로","t":"groupByLen은 길이별로 단어를 배열에 모은다(입력 순서 유지). mergeCounts는 같은 키의 값을 더해 합친다. valueSum은 모든 숫자 값을 더하고 빈 객체는 0. hasPath는 키 배열 경로를 따라 내려가며 중간에 없으면 false. 이때 중간 값이 객체가 아닐 수 있으므로(예: 숫자·문자열) `in` 연산자를 쓰기 전에 `typeof cur === \"object\"`인지 확인해야 한다. JS에서 원시값에 `in`을 쓰면 TypeError가 나기 때문이다."}],"code":{"c":"function pick(obj, keys) {\n  const res = {};\n  for (const k of keys) {\n    if (k in obj) res[k] = obj[k];\n  }\n  return res;\n}\n\nfunction hasPath(obj, path) {\n  let cur = obj;\n  for (const k of path) {\n    if (cur === null || typeof cur !== \"object\" || !(k in cur)) return false;\n    cur = cur[k];\n  }\n  return true;\n}","cap":"pick은 존재하는 키만, hasPath는 경로를 따라 내려가며 null·비객체를 방어."},"key":["pick은 `k in obj`로 존재 키만 선택","invert는 값↔키 교환","mergeCounts는 같은 키 값을 더함","hasPath는 매 단계 null·비객체(원시값)·키 부재를 방어 (원시값에 `in` 쓰면 TypeError)"]}},{"t":"집계와 경로 탐색","q":[{"t":"code","run":"js","k":"jsb-group-by-len","q":"단어 배열을 글자 수별로 묶어 객체로 반환하는 groupByLen 함수를 작성하세요. 키는 길이, 값은 해당 길이의 단어 배열(입력 순서 유지)입니다.","src":"function groupByLen(words){\n  // TODO\n  \n}","tests":[{"in":"groupByLen([\"a\",\"bb\",\"cc\",\"ddd\"])","out":"{\"1\":[\"a\"],\"2\":[\"bb\",\"cc\"],\"3\":[\"ddd\"]}"},{"in":"groupByLen([\"hi\",\"by\"])","out":"{\"2\":[\"hi\",\"by\"]}"},{"in":"groupByLen([\"one\"])","out":"{\"3\":[\"one\"]}"}],"edge":[{"in":"groupByLen([])","out":"{}"}],"ex":"단어 길이를 키로 삼아, 키가 없으면 빈 배열을 만들고 push로 추가합니다.\n💡 개념: 그룹핑은 '키가 없으면 초기화 후 추가' 패턴의 반복입니다.\n🛠 실무: 데이터를 카테고리별로 묶는 집계 로직의 기본형입니다."},{"t":"code","run":"js","k":"jsb-merge-counts","q":"두 개의 카운트 객체를 병합하되 같은 키의 값은 더하는 mergeCounts(a, b) 함수를 작성하세요.","src":"function mergeCounts(a, b){\n  // TODO\n  \n}","tests":[{"in":"mergeCounts({a:1,b:2},{b:3,c:1})","out":"{\"a\":1,\"b\":5,\"c\":1}"},{"in":"mergeCounts({x:1},{y:2})","out":"{\"x\":1,\"y\":2}"},{"in":"mergeCounts({a:2},{a:3})","out":"{\"a\":5}"}],"edge":[{"in":"mergeCounts({},{})","out":"{}"}],"ex":"a를 복사해 시작한 뒤, b의 각 키에 대해 기존 값(없으면 0)에 더합니다.\n💡 개념: (r[k]||0) 관용구로 미존재 키를 0으로 안전하게 처리합니다.\n🛠 실무: 빈도·통계 데이터를 합산할 때 자주 등장합니다."},{"t":"code","run":"js","k":"jsb-value-sum","q":"객체의 모든 숫자 값을 더한 합을 반환하는 valueSum 함수를 작성하세요. 빈 객체는 0을 반환합니다.","src":"function valueSum(obj){\n  // TODO\n  \n}","tests":[{"in":"valueSum({a:1,b:2,c:3})","out":"6"},{"in":"valueSum({x:10})","out":"10"},{"in":"valueSum({a:5,b:-2})","out":"3"}],"edge":[{"in":"valueSum({})","out":"0"}],"ex":"for...in으로 키를 순회하며 각 값을 누적합니다.\n💡 개념: Object.values(obj).reduce(...)로도 동일하게 구현할 수 있습니다.\n🛠 실무: 장바구니 금액 합계 같은 값 집계에 쓰입니다."},{"t":"code","run":"js","k":"jsb-has-path","q":"중첩 객체에서 키 배열로 표현된 경로가 존재하는지 검사하는 hasPath(obj, path) 함수를 작성하세요. true 또는 false를 반환합니다.","src":"function hasPath(obj, path){\n  // TODO\n  \n}","tests":[{"in":"hasPath({a:{b:{c:1}}}, [\"a\",\"b\",\"c\"])","out":"true"},{"in":"hasPath({a:{b:1}}, [\"a\",\"x\"])","out":"false"},{"in":"hasPath({a:1}, [\"a\"])","out":"true"},{"in":"hasPath({a:{b:2}}, [\"a\",\"b\",\"c\"])","out":"false"}],"edge":[{"in":"hasPath({}, [\"a\"])","out":"false"}],"ex":"현재 위치가 객체이고 해당 키를 가질 때만 한 단계 내려가며, 중간에 실패하면 즉시 false를 반환합니다.\n💡 개념: 원시값에 도달하면 더 내려갈 수 없으므로 타입 검사가 필요합니다.\n🛠 실무: 깊게 중첩된 설정·응답 데이터를 안전하게 탐색할 때 씁니다."}],"th":{"sum":"**객체 변환** 실습. 키 선택(pick)·키-값 뒤집기·그룹핑·카운트 병합·값 합계·중첩 경로 검사를 구현한다.","body":[{"h":"집계와 경로","t":"groupByLen은 길이별로 단어를 배열에 모은다(입력 순서 유지). mergeCounts는 같은 키의 값을 더해 합친다. valueSum은 모든 숫자 값을 더하고 빈 객체는 0. hasPath는 키 배열 경로를 따라 내려가며 중간에 없으면 false. 이때 중간 값이 객체가 아닐 수 있으므로(예: 숫자·문자열) `in` 연산자를 쓰기 전에 `typeof cur === \"object\"`인지 확인해야 한다. JS에서 원시값에 `in`을 쓰면 TypeError가 나기 때문이다."},{"h":"선택과 뒤집기","t":"pick은 주어진 키 목록 중 존재하는 것만 새 객체로 담는다(없는 키 무시). invert는 값을 새 키로, 키를 새 값으로 뒤집는다. keyByFirst는 첫 글자를 키로 하되 같은 첫 글자면 나중 단어가 덮어쓴다."}],"code":{"c":"function pick(obj, keys) {\n  const res = {};\n  for (const k of keys) {\n    if (k in obj) res[k] = obj[k];\n  }\n  return res;\n}\n\nfunction hasPath(obj, path) {\n  let cur = obj;\n  for (const k of path) {\n    if (cur === null || typeof cur !== \"object\" || !(k in cur)) return false;\n    cur = cur[k];\n  }\n  return true;\n}","cap":"pick은 존재하는 키만, hasPath는 경로를 따라 내려가며 null·비객체를 방어."},"key":["pick은 `k in obj`로 존재 키만 선택","invert는 값↔키 교환","mergeCounts는 같은 키 값을 더함","hasPath는 매 단계 null·비객체(원시값)·키 부재를 방어 (원시값에 `in` 쓰면 TypeError)"]}}]},{"t":"고차함수와 함수형 프로그래밍","l":[{"t":"배열·객체를 변환하는 고차함수","q":[{"t":"code","run":"js","k":"jsm-mapkeys","q":"객체의 각 키를 변환 함수 fn에 통과시켜 새 키로 바꾼 객체를 반환하세요. 값은 그대로 유지합니다.","src":"function mapKeys(obj, fn){\n  // TODO\n  \n}","tests":[{"in":"mapKeys({a:1,b:2}, function(k){return k.toUpperCase();})","out":"{\"A\":1,\"B\":2}"},{"in":"mapKeys({name:1}, function(k){return k+'_';})","out":"{\"name_\":1}"},{"in":"mapKeys({x:10,y:20}, function(k){return k+k;})","out":"{\"xx\":10,\"yy\":20}"}],"edge":[{"in":"mapKeys({}, function(k){return k;})","out":"{}"}],"ex":"for...in 으로 각 키를 순회하며 fn(key)를 새 키로 사용합니다.\n💡 개념: 객체는 순서 없는 키-값 집합이며 hasOwnProperty로 상속 속성을 배제합니다.\n🛠 실무: API 응답의 snake_case 키를 camelCase로 바꾸는 등 데이터 정규화에 자주 씁니다."},{"t":"code","run":"js","k":"jsm-filterby","q":"객체 배열 arr에서 o[key]가 value와 일치하는 요소만 골라 배열로 반환하세요.","src":"function filterBy(arr, key, value){\n  // TODO\n  \n}","tests":[{"in":"filterBy([{a:1},{a:2},{a:1}], 'a', 1)","out":"[{\"a\":1},{\"a\":1}]"},{"in":"filterBy([{t:'x'},{t:'y'}], 't', 'y')","out":"[{\"t\":\"y\"}]"},{"in":"filterBy([{n:1},{n:2}], 'n', 3)","out":"[]"}],"edge":[{"in":"filterBy([], 'a', 1)","out":"[]"}],"ex":"Array.prototype.filter 로 조건을 만족하는 요소만 남깁니다.\n💡 개념: filter는 원본을 변경하지 않고 새 배열을 만드는 순수 함수입니다.\n🛠 실무: 목록 화면의 검색·필터 기능 구현의 기본 패턴입니다."},{"t":"code","run":"js","k":"jsm-reducesum","q":"숫자 배열의 모든 값을 reduce로 더한 합계를 반환하세요.","src":"function reduceSum(arr){\n  // TODO\n  \n}","tests":[{"in":"reduceSum([1,2,3])","out":"6"},{"in":"reduceSum([10,-5,5])","out":"10"},{"in":"reduceSum([100])","out":"100"}],"edge":[{"in":"reduceSum([])","out":"0"}],"ex":"reduce의 초깃값을 0으로 두면 빈 배열도 안전하게 처리됩니다.\n💡 개념: reduce는 배열을 하나의 누적값으로 접는(fold) 범용 고차함수입니다.\n🛠 실무: 장바구니 총액, 통계 집계 등 누적 계산의 표준 도구입니다."},{"t":"code","run":"js","k":"jsm-pipe","q":"여러 함수를 인자로 받아, 값을 왼쪽에서 오른쪽 순서로 통과시키는 새 함수를 반환하세요. pipe(f,g)(x)는 g(f(x))와 같습니다.","src":"function pipe(){\n  // TODO\n  \n}","tests":[{"in":"pipe(function(x){return x+1;}, function(x){return x*2;})(5)","out":"12"},{"in":"pipe(function(x){return x*3;})(4)","out":"12"},{"in":"pipe(function(x){return x-1;}, function(x){return x-1;}, function(x){return x-1;})(10)","out":"7"}],"edge":[{"in":"pipe()(7)","out":"7"}],"ex":"arguments를 배열로 만든 뒤 reduce로 왼쪽부터 함수를 차례로 적용합니다.\n💡 개념: 함수 합성(composition)은 작은 함수를 조립해 복잡한 변환을 만드는 함수형의 핵심입니다.\n🛠 실무: 데이터 파이프라인, 미들웨어 체인 구성에 사용됩니다."},{"t":"code","run":"js","k":"jsm-compose","q":"여러 함수를 인자로 받아, 값을 오른쪽에서 왼쪽 순서로 통과시키는 새 함수를 반환하세요. compose(f,g)(x)는 f(g(x))와 같습니다.","src":"function compose(){\n  // TODO\n  \n}","tests":[{"in":"compose(function(x){return x+1;}, function(x){return x*2;})(5)","out":"11"},{"in":"compose(function(x){return x*3;})(4)","out":"12"},{"in":"compose(function(x){return x+'!';}, function(x){return x+'?';})('hi')","out":"\"hi?!\""}],"edge":[{"in":"compose()(9)","out":"9"}],"ex":"reduceRight로 오른쪽부터 적용하면 수학적 함수 합성 순서와 같아집니다.\n💡 개념: compose는 pipe의 반대 방향이며 f∘g 표기와 일치합니다.\n🛠 실무: HOC(고차 컴포넌트) 래핑, 데코레이터 결합에 활용됩니다."},{"t":"code","run":"js","k":"jsm-once","q":"함수 fn을 감싸, 처음 한 번만 실제로 실행하고 이후 호출에서는 첫 결과를 그대로 반환하는 함수를 반환하세요. (테스트는 내부 카운터로 실제 실행 횟수를 확인합니다)","src":"function once(fn){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var c=0; var g=once(function(){ return ++c; }); g(); g(); return c; })()","out":"1"},{"in":"(function(){ var g=once(function(x){ return x*2; }); g(5); return g(99); })()","out":"10"},{"in":"(function(){ var g=once(function(){ return 'done'; }); return g(); })()","out":"\"done\""}],"edge":[{"in":"(function(){ var c=0; var g=once(function(){ c++; }); g(); g(); g(); return c; })()","out":"1"}],"ex":"클로저로 called 플래그와 result를 기억해 재실행을 막습니다.\n💡 개념: 한 번만 실행 보장은 초기화 로직에서 흔한 요구사항입니다.\n🛠 실무: 앱 부트스트랩, 이벤트 리스너 1회 등록 등에 사용됩니다."},{"t":"code","run":"js","k":"jsm-memoize","q":"단일 인자 함수 fn을 감싸, 같은 인자로 재호출되면 캐시된 결과를 돌려주는 함수를 반환하세요. (테스트는 실제 실행 횟수를 확인합니다)","src":"function memoize(fn){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var calls=0; var m=memoize(function(x){ calls++; return x*2; }); m(5); m(5); return calls; })()","out":"1"},{"in":"(function(){ var m=memoize(function(x){ return x*x; }); return m(6); })()","out":"36"},{"in":"(function(){ var calls=0; var m=memoize(function(x){ calls++; return x; }); m(1); m(2); m(1); return calls; })()","out":"2"}],"edge":[{"in":"(function(){ var m=memoize(function(x){ return x+1; }); m(0); return m(0); })()","out":"1"}],"ex":"인자를 키로 하는 캐시 객체에 결과를 저장하고 hasOwnProperty로 존재를 확인합니다.\n💡 개념: 메모이제이션은 순수 함수의 반복 계산을 캐싱해 속도를 높입니다.\n🛠 실무: 비싼 연산(파싱, 셀렉터, 렌더 계산) 최적화에 널리 쓰입니다."},{"t":"code","run":"js","k":"jsm-unique","q":"배열에서 중복을 제거해 처음 등장한 순서대로 유지한 새 배열을 반환하세요.","src":"function unique(arr){\n  // TODO\n  \n}","tests":[{"in":"unique([1,2,2,3,3,3])","out":"[1,2,3]"},{"in":"unique([5,5,5])","out":"[5]"},{"in":"unique([1,2,3])","out":"[1,2,3]"}],"edge":[{"in":"unique([])","out":"[]"}],"perf":{"setup":"var A=Array.from({length:50000},function(_,i){return i%1000;})","in":"unique(A).length","out":"1000","ms":60},"ex":"해시(객체/Set)로 이미 본 값을 O(1)에 판별하면 전체가 O(n)입니다.\n💡 개념: indexOf를 반복하면 O(n²)이 되지만 해시 조회는 O(1)입니다.\n🛠 실무: 대용량 로그·ID 목록 중복 제거에서 성능 차이가 큽니다."},{"t":"code","run":"js","k":"jsm-firstdup","q":"배열을 앞에서부터 훑어 처음으로 두 번째 등장하는 값을 반환하세요. 중복이 없으면 -1을 반환합니다.","src":"function firstDuplicate(arr){\n  // TODO\n  \n}","tests":[{"in":"firstDuplicate([1,2,3,2,4])","out":"2"},{"in":"firstDuplicate([5,1,5,1])","out":"5"},{"in":"firstDuplicate([1,2,3])","out":"-1"}],"edge":[{"in":"firstDuplicate([])","out":"-1"}],"perf":{"setup":"var A=Array.from({length:50000},function(_,i){return i;})","in":"firstDuplicate(A)","out":"-1","ms":60},"ex":"본 값을 해시에 기록하며 한 번만 순회하면 O(n)입니다.\n💡 개념: 이중 반복(O(n²)) 대신 상태 저장으로 한 번의 스캔이면 충분합니다.\n🛠 실무: 스트림에서 첫 중복 감지, 사이클 탐지 전처리 등에 쓰입니다."}],"th":{"sum":"**고차함수·함수형** 실습. map/filter/reduce와 pipe·compose·once·memoize 같은 함수를 반환하는 함수를 만든다.","body":[{"h":"변환 고차함수","t":"객체 키 변환은 각 키를 `fn`에 통과시켜 새 키로(값 유지). 객체 배열 필터는 `o[key] === value`인 것만. 합계는 `reduce((a,b)=>a+b, 0)`. 이들은 원본을 바꾸지 않고 새 값을 반환한다."},{"h":"함수를 반환하는 함수","t":"pipe(f,g)(x)=g(f(x)) 왼→오, compose(f,g)(x)=f(g(x)) 오→왼로 함수들을 합성한다. once는 클로저에 실행 여부·결과를 저장해 첫 호출만 실제 실행. memoize는 인자를 키로 캐시에 결과를 저장해 재호출 시 캐시를 반환한다."}],"code":{"c":"const pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\nconst compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\n\nfunction memoize(fn) {\n  const cache = new Map();\n  return arg => {\n    if (cache.has(arg)) return cache.get(arg);\n    const r = fn(arg);\n    cache.set(arg, r);\n    return r;\n  };\n}","cap":"pipe는 왼→오, compose는 오→왼. memoize는 클로저 캐시."},"key":["pipe = 왼→오, compose = 오→왼 합성","reduce로 배열을 하나의 값으로 접기","once/memoize는 클로저에 상태(실행·캐시) 저장","고차함수는 원본 불변, 새 값 반환"]}}]},{"t":"클로저와 상태 캡슐화","l":[{"t":"클로저로 상태를 감추기","q":[{"t":"code","run":"js","k":"jsm-makecounter","q":"호출할 때마다 1씩 증가한 값을 반환하는 카운터 함수를 반환하세요. 시작값 start(기본 0) 다음 값부터 반환합니다.","src":"function makeCounter(start){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var c=makeCounter(); c(); c(); return c(); })()","out":"3"},{"in":"(function(){ var c=makeCounter(); return c(); })()","out":"1"},{"in":"(function(){ var c=makeCounter(100); c(); return c(); })()","out":"102"}],"edge":[{"in":"(function(){ var c=makeCounter(5); return c(); })()","out":"6"}],"ex":"내부 변수 n을 클로저로 유지하며 호출마다 증가시킵니다.\n💡 개념: 클로저는 함수가 정의된 스코프의 변수를 계속 참조하게 합니다.\n🛠 실무: 고유 ID 생성기, 재시도 횟수 추적 등에 사용됩니다."},{"t":"code","run":"js","k":"jsm-curryadd","q":"curryAdd(a)(b) 형태로 호출되어 a+b를 반환하는 커링 함수를 만드세요.","src":"function curryAdd(a){\n  // TODO\n  \n}","tests":[{"in":"curryAdd(2)(3)","out":"5"},{"in":"curryAdd(-1)(1)","out":"0"},{"in":"curryAdd(10)(0)","out":"10"}],"edge":[{"in":"curryAdd(0)(0)","out":"0"}],"ex":"바깥 함수의 인자 a를 클로저로 기억한 새 함수를 반환합니다.\n💡 개념: 커링은 다인자 함수를 인자 하나씩 받는 함수 사슬로 바꾸는 기법입니다.\n🛠 실무: 부분 적용으로 설정을 고정한 특화 함수를 만들 때 씁니다."},{"t":"code","run":"js","k":"jsm-createstack","q":"push(x), pop(), peek(), size() 메서드를 가진 스택 객체를 반환하세요. 테스트는 메서드를 순서대로 호출한 뒤 결과를 확인합니다.","src":"function createStack(){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var s=createStack(); s.push(1); s.push(2); s.pop(); return s.size(); })()","out":"1"},{"in":"(function(){ var s=createStack(); s.push(5); s.push(9); return s.peek(); })()","out":"9"},{"in":"(function(){ var s=createStack(); s.push('a'); return s.pop(); })()","out":"\"a\""}],"edge":[{"in":"(function(){ var s=createStack(); return s.size(); })()","out":"0"}],"ex":"내부 배열을 클로저로 감추고 메서드로만 접근하게 하여 캡슐화합니다.\n💡 개념: 외부에서 배열에 직접 접근할 수 없으니 불변식이 지켜집니다.\n🛠 실무: 실행 취소(undo) 히스토리, 괄호 매칭 등 LIFO 자료구조에 쓰입니다."},{"t":"code","run":"js","k":"jsm-bankaccount","q":"deposit(x), withdraw(x), balance() 메서드를 가진 계좌 객체를 반환하세요. 초기 잔액 initial(기본 0). withdraw는 잔액이 부족하면 false를 반환하고, 성공하면 새 잔액을 반환합니다.","src":"function bankAccount(initial){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var a=bankAccount(100); a.deposit(50); a.withdraw(30); return a.balance(); })()","out":"120"},{"in":"(function(){ var a=bankAccount(10); return a.withdraw(50); })()","out":"false"},{"in":"(function(){ var a=bankAccount(0); a.deposit(200); return a.balance(); })()","out":"200"}],"edge":[{"in":"(function(){ var a=bankAccount(); return a.balance(); })()","out":"0"}],"ex":"잔액 변수를 클로저로 숨겨 검증된 메서드로만 변경되게 합니다.\n💡 개념: 상태 캡슐화로 잘못된 인출 같은 불변식 위반을 막습니다.\n🛠 실무: 결제 잔액, 재고 수량처럼 규칙이 있는 상태 관리에 적합합니다."},{"t":"code","run":"js","k":"jsm-rangegen","q":"start부터 end 미만까지 step(기본 1) 간격의 정수 배열을 반환하세요.","src":"function rangeGen(start, end, step){\n  // TODO\n  \n}","tests":[{"in":"rangeGen(0,5)","out":"[0,1,2,3,4]"},{"in":"rangeGen(1,10,2)","out":"[1,3,5,7,9]"},{"in":"rangeGen(3,6)","out":"[3,4,5]"}],"edge":[{"in":"rangeGen(0,0)","out":"[]"}],"ex":"for 루프로 start에서 시작해 step씩 더하며 end 미만까지 채웁니다.\n💡 개념: 반열린 구간 [start, end)는 길이 계산과 이어붙이기에 편리합니다.\n🛠 실무: 페이지네이션 번호, 타임라인 눈금 생성 등에 쓰입니다."},{"t":"code","run":"js","k":"jsm-accumulator","q":"호출할 때마다 인자를 누적한 총합을 반환하는 함수를 반환하세요.","src":"function makeAccumulator(){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var acc=makeAccumulator(); acc(10); acc(20); return acc(5); })()","out":"35"},{"in":"(function(){ var acc=makeAccumulator(); return acc(7); })()","out":"7"},{"in":"(function(){ var acc=makeAccumulator(); acc(-5); return acc(5); })()","out":"0"}],"edge":[{"in":"(function(){ var acc=makeAccumulator(); return acc(0); })()","out":"0"}],"ex":"total을 클로저로 유지하며 매 호출 인자를 더해 반환합니다.\n💡 개념: 클로저는 호출 사이에 상태를 보존하는 가장 단순한 수단입니다.\n🛠 실무: 스크롤 누적 거리, 점수 합산 같은 러닝 토탈에 쓰입니다."},{"t":"code","run":"js","k":"jsm-toggle","q":"호출할 때마다 a와 b를 번갈아 반환하는 함수를 반환하세요. 첫 호출은 a를 반환합니다.","src":"function toggle(a, b){\n  // TODO\n  \n}","tests":[{"in":"(function(){ var t=toggle('on','off'); return t(); })()","out":"\"on\""},{"in":"(function(){ var t=toggle('on','off'); t(); return t(); })()","out":"\"off\""},{"in":"(function(){ var t=toggle(1,0); t(); t(); return t(); })()","out":"1"}],"edge":[{"in":"(function(){ var t=toggle(true,false); t(); t(); t(); return t(); })()","out":"false"}],"ex":"불리언 플래그를 뒤집으며 그에 맞는 값을 반환합니다.\n💡 개념: 상태 기계의 가장 작은 형태로, 두 상태를 오갑니다.\n🛠 실무: 다크모드 토글, 정렬 방향 전환 등 UI 상태에 쓰입니다."}],"th":{"sum":"**클로저로 상태 캡슐화** 실습. 함수가 외부 변수를 기억하는 성질로 카운터·스택·계좌 같은 비공개 상태를 만든다.","body":[{"h":"클로저의 원리","t":"내부 함수는 자신을 감싼 함수의 변수를 계속 참조·기억한다. 이 변수는 밖에서 직접 못 만지므로 캡슐화된 비공개 상태가 된다. 카운터는 `count`를 감춰두고 호출 때마다 증가한 값을 반환한다."},{"h":"상태를 가진 객체·함수","t":"스택/계좌는 내부 배열·잔액을 클로저로 감추고 메서드(push/pop, deposit/withdraw)만 노출한다. curryAdd(a)(b)는 a를 기억한 함수를 반환해 나중 b와 더한다. 누적 합계 함수, a·b 번갈아 반환도 모두 클로저에 상태를 담는다."}],"code":{"c":"function makeCounter(start = 0) {\n  let count = start;\n  return () => ++count;  // start 다음 값부터\n}\nconst c = makeCounter(0);\nc();  // 1\nc();  // 2\n\nfunction createStack() {\n  const items = [];\n  return {\n    push: x => items.push(x),\n    pop: () => items.pop(),\n    peek: () => items[items.length - 1],\n    size: () => items.length,\n  };\n}","cap":"내부 변수를 클로저로 감춰 비공개 상태로 관리."},"key":["클로저 = 내부 함수가 외부 변수를 기억","비공개 상태를 만들어 캡슐화","메서드만 노출하고 데이터는 감춤","curry는 앞 인자를 기억한 함수를 반환"]}}]},{"t":"재귀와 데이터 변환","l":[{"t":"재귀로 중첩 구조 다루기","q":[{"t":"code","run":"js","k":"jsm-deepsum","q":"임의로 중첩된 숫자 배열의 모든 숫자를 재귀적으로 더한 합을 반환하세요.","src":"function deepSum(arr){\n  // TODO\n  \n}","tests":[{"in":"deepSum([1,[2,3],[4,[5]]])","out":"15"},{"in":"deepSum([1,2,3])","out":"6"},{"in":"deepSum([[[[10]]]])","out":"10"}],"edge":[{"in":"deepSum([])","out":"0"}],"ex":"요소가 배열이면 재귀 호출, 아니면 값을 더합니다.\n💡 개념: 재귀는 자기와 같은 구조의 부분 문제로 자연스럽게 분해됩니다.\n🛠 실무: 트리 형태 데이터의 총합·집계 계산에 쓰입니다."},{"t":"code","run":"js","k":"jsm-flattendeep","q":"임의로 중첩된 배열을 완전히 평탄화하여 1차원 배열로 반환하세요.","src":"function flattenDeep(arr){\n  // TODO\n  \n}","tests":[{"in":"flattenDeep([1,[2,[3,[4]]]])","out":"[1,2,3,4]"},{"in":"flattenDeep([1,2,3])","out":"[1,2,3]"},{"in":"flattenDeep([[1],[2],[3]])","out":"[1,2,3]"}],"edge":[{"in":"flattenDeep([])","out":"[]"}],"perf":{"setup":"var A=Array.from({length:50000},function(_,i){return [i];})","in":"flattenDeep(A).length","out":"50000","ms":60},"ex":"결과 배열에 push로 모으면 concat 반복(O(n²))을 피해 O(n)이 됩니다.\n💡 개념: concat은 매번 새 배열을 복사하므로 재귀 누적에 쓰면 비효율적입니다.\n🛠 실무: 대량 중첩 데이터 평탄화에서 push 누적 방식이 훨씬 빠릅니다."},{"t":"code","run":"js","k":"jsm-factorial","q":"음이 아닌 정수 n의 팩토리얼(n!)을 재귀로 계산해 반환하세요. 0! = 1.","src":"function factorial(n){\n  // TODO\n  \n}","tests":[{"in":"factorial(5)","out":"120"},{"in":"factorial(1)","out":"1"},{"in":"factorial(6)","out":"720"}],"edge":[{"in":"factorial(0)","out":"1"}],"ex":"n&lt;=1이면 1을 반환하는 기저 조건이 재귀를 멈춥니다.\n💡 개념: 모든 재귀에는 무한 재귀를 막는 기저 사례(base case)가 필요합니다.\n🛠 실무: 조합·순열 계산 등 수학적 반복 정의를 코드로 옮길 때 씁니다."},{"t":"code","run":"js","k":"jsm-sumnested","q":"중첩된 객체의 모든 숫자 값을 재귀적으로 더한 합을 반환하세요. 값이 객체이면 그 안으로 내려갑니다.","src":"function sumNested(obj){\n  // TODO\n  \n}","tests":[{"in":"sumNested({a:1,b:{c:2,d:3}})","out":"6"},{"in":"sumNested({a:{b:{c:5}}})","out":"5"},{"in":"sumNested({x:10,y:20})","out":"30"}],"edge":[{"in":"sumNested({})","out":"0"}],"ex":"값이 객체이면 재귀, 아니면 숫자를 더합니다. null은 typeof가 object이므로 주의합니다.\n💡 개념: 객체 트리 순회는 배열 재귀와 동일한 분할 정복 패턴입니다.\n🛠 실무: 중첩 설정·집계 JSON에서 특정 필드 합산에 응용됩니다."},{"t":"code","run":"js","k":"jsm-treedepth","q":"{value, children:[]} 형태의 트리 노드에서 최대 깊이를 반환하세요. 리프 노드(자식 없음)의 깊이는 1입니다.","src":"function treeDepth(node){\n  // TODO\n  \n}","tests":[{"in":"treeDepth({value:1,children:[]})","out":"1"},{"in":"treeDepth({value:1,children:[{value:2,children:[]}]})","out":"2"},{"in":"treeDepth({value:1,children:[{value:2,children:[{value:3,children:[]}]},{value:4,children:[]}]})","out":"3"}],"edge":[{"in":"treeDepth({value:9,children:[]})","out":"1"}],"ex":"자식이 없으면 1, 있으면 자식 깊이의 최댓값에 1을 더합니다.\n💡 개념: 트리 높이는 부분 트리 높이로 정의되는 대표적 재귀 문제입니다.\n🛠 실무: 조직도, 카테고리 트리, DOM 깊이 계산 등에 쓰입니다."},{"t":"code","run":"js","k":"jsm-jsonpathget","q":"객체 obj에서 'a.b.c' 같은 점 경로(path)를 따라 값을 꺼내 반환하세요. 경로 도중 존재하지 않으면 null을 반환합니다.","src":"function jsonPathGet(obj, path){\n  // TODO\n  \n}","tests":[{"in":"jsonPathGet({a:{b:{c:42}}}, 'a.b.c')","out":"42"},{"in":"jsonPathGet({a:{b:1}}, 'a.b')","out":"1"},{"in":"jsonPathGet({user:{name:'kim'}}, 'user.name')","out":"\"kim\""}],"edge":[{"in":"jsonPathGet({a:1}, 'x.y')","out":"null"},{"in":"jsonPathGet({a:{b:2}}, 'a.z')","out":"null"}],"ex":"경로를 점으로 나눠 순서대로 내려가되, 키가 없으면 null로 중단합니다.\n💡 개념: 안전한 중첩 접근은 각 단계에서 존재 여부를 확인해야 합니다.\n🛠 실무: 설정 파일, API 응답에서 깊은 값을 안전하게 꺼낼 때 유용합니다."},{"t":"code","run":"js","k":"jsm-countleaves","q":"{children:[]} 형태의 트리에서 리프 노드(자식이 없는 노드)의 개수를 재귀로 세어 반환하세요.","src":"function countLeaves(node){\n  // TODO\n  \n}","tests":[{"in":"countLeaves({children:[]})","out":"1"},{"in":"countLeaves({children:[{children:[]},{children:[]}]})","out":"2"},{"in":"countLeaves({children:[{children:[{children:[]},{children:[]}]},{children:[]}]})","out":"3"}],"edge":[{"in":"countLeaves({children:[{children:[]}]})","out":"1"}],"ex":"자식이 없으면 1, 있으면 각 자식의 리프 수를 합칩니다.\n💡 개념: 리프 카운트는 합계형 트리 재귀의 전형입니다.\n🛠 실무: 파일 트리의 파일 수, 조직도 말단 인원 계산 등에 쓰입니다."}],"th":{"sum":"**재귀로 중첩 구조** 다루기. 배열/객체/트리를 재귀로 합산·평탄화하고, base case를 정확히 둔다.","body":[{"h":"중첩 합산·평탄화","t":"중첩 숫자 배열 합은 요소가 배열이면 재귀 호출, 숫자면 더한다. 완전 평탄화도 같은 분기로 결과를 이어붙인다. 팩토리얼은 `0! = 1`을 base case로 `n * factorial(n-1)`. 중첩 객체 값 합은 값이 객체면 내려가고 숫자면 더한다."},{"h":"트리와 경로","t":"트리 최대 깊이는 리프가 1이고 `1 + max(자식들의 깊이)`. 리프 개수는 자식이 없으면 1, 있으면 자식들의 리프 합. 점 경로 `a.b.c`는 경로를 쪼개 따라 내려가되 중간에 없으면 null."}],"code":{"c":"function deepSum(arr) {\n  let total = 0;\n  for (const x of arr) {\n    total += Array.isArray(x) ? deepSum(x) : x;\n  }\n  return total;\n}\n\nfunction maxDepth(node) {\n  if (!node.children || node.children.length === 0) return 1;\n  return 1 + Math.max(...node.children.map(maxDepth));\n}","cap":"요소가 배열이면 재귀, 아니면 값 처리. 리프 깊이는 1."},"key":["재귀는 base case(리프·빈 구조)를 먼저 정의","요소가 배열/객체면 내려가고 아니면 값 처리","최대 깊이 = 1 + max(자식 깊이), 리프=1","점 경로는 split 후 단계별 null 방어"]}}]},{"t":"직접 구현 — 함수 (테스트 통과)","l":[{"t":"조건·숫자 함수 구현","q":[{"t":"code","k":"직접 구현","run":"js","q":"짝수면 true, 홀수면 false를 반환하는 함수 isEven(n) 을 구현하세요. 모든 테스트가 통과해야 정답입니다.","src":"function isEven(n){\n  // n이 짝수면 true 를 반환하세요\n  \n}","tests":[{"in":"isEven(2)","out":"true"},{"in":"isEven(3)","out":"false"},{"in":"isEven(0)","out":"true"},{"in":"isEven(-4)","out":"true"}],"ex":"return n % 2 === 0; — 나머지 연산자로 2로 나눈 나머지가 0인지 봅니다.\n💡 개념: %는 나머지, ===는 타입까지 비교하는 엄격한 동등입니다.\n🛠 실무: 짝/홀 판정, 페이지네이션 줄무늬, 샤딩 키 분배 등에 나머지 연산이 쓰입니다."},{"t":"code","k":"직접 구현","run":"js","q":"두 수 중 더 큰 값을 반환하는 함수 max2(a, b) 를 구현하세요. (내장 Math.max 없이)","src":"function max2(a, b){\n  // 더 큰 값을 반환하세요\n  \n}","tests":[{"in":"max2(3,7)","out":"7"},{"in":"max2(9,2)","out":"9"},{"in":"max2(5,5)","out":"5"},{"in":"max2(-1,-4)","out":"-1"}],"ex":"return a > b ? a : b; — 삼항 연산자로 조건에 따라 값을 고릅니다.\n💡 개념: 조건 ? A : B 는 조건이 참이면 A, 아니면 B 를 값으로 갖습니다.\n🛠 실무: null 병합·기본값 선택 등 짧은 분기에서 if 대신 삼항을 자주 씁니다."},{"t":"code","k":"직접 구현","run":"js","q":"점수를 받아 90 이상 \"A\", 80 이상 \"B\", 그 외 \"C\" 를 반환하는 grade(score) 를 구현하세요.","src":"function grade(score){\n  // 등급 문자열을 반환하세요\n  \n}","tests":[{"in":"grade(95)","out":"\"A\""},{"in":"grade(85)","out":"\"B\""},{"in":"grade(70)","out":"\"C\""},{"in":"grade(90)","out":"\"A\""},{"in":"grade(80)","out":"\"B\""}],"ex":"if(score>=90)return \"A\"; else if(score>=80)return \"B\"; return \"C\"; — 경계값(90, 80) 포함 여부가 핵심입니다.\n💡 개념: 조건은 위에서 아래로 평가되므로 높은 기준부터 검사해야 합니다.\n🛠 실무: 경계값 테스트(90, 89, 80)는 버그가 가장 많이 숨는 곳이라 반드시 케이스로 둡니다."}],"th":{"sum":"조건·숫자·배열·문자열 **기본 함수를 직접 구현**해 모든 테스트를 통과시킨다. 경계 조건을 정확히 처리한다.","body":[{"h":"조건·숫자 함수","t":"isEven은 `n % 2 === 0`. max2는 내장 없이 `a > b ? a : b`. grade는 90 이상 \"A\", 80 이상 \"B\", 그 외 \"C\"를 순서대로 비교(높은 기준부터). 경계값(80, 90 정확히)에서 어느 등급인지 정확히 맞춘다."},{"h":"배열·문자열 함수","t":"sumArr는 for 누적, 빈 배열은 0. reverseStr는 뒤에서부터 이어붙이거나 양끝 스왑. countEven은 짝수만 카운트. isPalindrome은 양끝 포인터로 좁혀 비교하거나 뒤집은 것과 같은지 확인한다."}],"code":{"c":"function grade(score) {\n  if (score >= 90) return \"A\";\n  if (score >= 80) return \"B\";\n  return \"C\";\n}\n\nfunction isPalindrome(s) {\n  let i = 0, j = s.length - 1;\n  while (i < j) {\n    if (s[i] !== s[j]) return false;\n    i++; j--;\n  }\n  return true;\n}","cap":"등급은 높은 기준부터 비교, 회문은 양끝 포인터로 검사."},"key":["grade는 높은 기준부터 순서대로 비교","빈 배열 합은 0","회문은 양끝 포인터 또는 뒤집기 비교","max2는 삼항 연산자로 내장 없이"]}},{"t":"배열·문자열 함수 구현","q":[{"t":"code","k":"직접 구현","run":"js","q":"배열의 모든 원소 합을 반환하는 sumArr(arr) 를 구현하세요. 빈 배열은 0.","src":"function sumArr(arr){\n  // 원소들의 합을 반환하세요\n  \n}","tests":[{"in":"sumArr([1,2,3])","out":"6"},{"in":"sumArr([])","out":"0"},{"in":"sumArr([5])","out":"5"},{"in":"sumArr([-1,1,-2,2])","out":"0"}],"ex":"let s=0; for(const x of arr) s+=x; return s; — 누적 변수는 0으로 시작합니다.\n💡 개념: reduce로도 arr.reduce((a,b)=>a+b, 0) 처럼 초깃값 0을 주면 빈 배열도 안전합니다.\n🛠 실무: 초깃값 없는 reduce는 빈 배열에서 에러가 나므로 항상 초깃값을 명시합니다."},{"t":"code","k":"직접 구현","run":"js","q":"문자열을 뒤집어 반환하는 reverseStr(s) 를 구현하세요.","src":"function reverseStr(s){\n  // 뒤집힌 문자열을 반환하세요\n  \n}","tests":[{"in":"reverseStr(\"abc\")","out":"\"cba\""},{"in":"reverseStr(\"a\")","out":"\"a\""},{"in":"reverseStr(\"한글\")","out":"\"글한\""},{"in":"reverseStr(\"\")","out":"\"\""}],"ex":"return s.split(\"\").reverse().join(\"\"); — 문자 배열로 쪼갠 뒤 뒤집어 다시 합칩니다.\n💡 개념: split(\"\")로 문자 단위 배열을 만들고 reverse()·join(\"\")으로 되돌립니다.\n🛠 실무: 이모지·조합형 문자는 코드포인트가 쪼개질 수 있어 [...s] 스프레드가 더 안전합니다."},{"t":"code","k":"직접 구현","run":"js","q":"배열에서 짝수의 개수를 반환하는 countEven(arr) 를 구현하세요.","src":"function countEven(arr){\n  // 짝수의 개수를 반환하세요\n  \n}","tests":[{"in":"countEven([1,2,3,4])","out":"2"},{"in":"countEven([1,3,5])","out":"0"},{"in":"countEven([2,4,6])","out":"3"},{"in":"countEven([])","out":"0"}],"ex":"return arr.filter(x=>x%2===0).length; — 조건에 맞는 원소만 남겨 개수를 셉니다.\n💡 개념: filter는 조건이 참인 원소로 새 배열을 만들고, length로 개수를 얻습니다.\n🛠 실무: 큰 배열에서 개수만 필요하면 filter 대신 for로 카운트해 중간 배열 생성을 피합니다."},{"t":"code","k":"직접 구현","run":"js","q":"회문(앞뒤가 같은 문자열)이면 true를 반환하는 isPalindrome(s) 를 구현하세요.","src":"function isPalindrome(s){\n  // 회문이면 true 를 반환하세요\n  \n}","tests":[{"in":"isPalindrome(\"level\")","out":"true"},{"in":"isPalindrome(\"hello\")","out":"false"},{"in":"isPalindrome(\"a\")","out":"true"},{"in":"isPalindrome(\"abba\")","out":"true"}],"ex":"return s === s.split(\"\").reverse().join(\"\"); — 원본과 뒤집은 문자열을 비교합니다.\n💡 개념: 앞서 만든 뒤집기 로직을 재사용해 동등 비교 한 번으로 판정합니다.\n🛠 실무: 대소문자·공백을 무시해야 하면 먼저 s.toLowerCase().replace(/\\s/g,\"\")로 정규화합니다."}],"th":{"sum":"조건·숫자·배열·문자열 **기본 함수를 직접 구현**해 모든 테스트를 통과시킨다. 경계 조건을 정확히 처리한다.","body":[{"h":"배열·문자열 함수","t":"sumArr는 for 누적, 빈 배열은 0. reverseStr는 뒤에서부터 이어붙이거나 양끝 스왑. countEven은 짝수만 카운트. isPalindrome은 양끝 포인터로 좁혀 비교하거나 뒤집은 것과 같은지 확인한다."},{"h":"조건·숫자 함수","t":"isEven은 `n % 2 === 0`. max2는 내장 없이 `a > b ? a : b`. grade는 90 이상 \"A\", 80 이상 \"B\", 그 외 \"C\"를 순서대로 비교(높은 기준부터). 경계값(80, 90 정확히)에서 어느 등급인지 정확히 맞춘다."}],"code":{"c":"function grade(score) {\n  if (score >= 90) return \"A\";\n  if (score >= 80) return \"B\";\n  return \"C\";\n}\n\nfunction isPalindrome(s) {\n  let i = 0, j = s.length - 1;\n  while (i < j) {\n    if (s[i] !== s[j]) return false;\n    i++; j--;\n  }\n  return true;\n}","cap":"등급은 높은 기준부터 비교, 회문은 양끝 포인터로 검사."},"key":["grade는 높은 기준부터 순서대로 비교","빈 배열 합은 0","회문은 양끝 포인터 또는 뒤집기 비교","max2는 삼항 연산자로 내장 없이"]}}]},{"t":"출력과 변수 (직접 짜기)","l":[{"t":"출력해보기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"console.log 로 Hello World 를 출력하세요.","src":"// 괄호 안에 \"Hello World\" 를 넣어보세요\nconsole.log();","expect":"Hello World","ex":"console.log(\"Hello World\"); — 따옴표로 감싸요."},{"t":"code","k":"코딩 과제","run":"js","q":"숫자 42 를 출력하세요. (따옴표 없이)","src":"console.log();","expect":"42","ex":"숫자는 따옴표 없이 console.log(42);"},{"t":"code","k":"코딩 과제","run":"js","q":"10 + 5 를 계산해서 결과(15)를 출력하세요.","src":"console.log(10 + );","expect":"15","ex":"console.log(10 + 5);"},{"t":"code","k":"코딩 과제","run":"js","q":"변수 city 에 \"Seoul\" 을 저장하고 출력하세요.","src":"let city = ;\nconsole.log(city);","expect":"Seoul","ex":"let city = \"Seoul\";"}],"th":{"sum":"**출력과 변수** 첫걸음. `console.log`로 값과 계산 결과를 출력하고 변수에 저장한다.","body":[{"h":"출력하기","t":"`console.log(값)`으로 화면에 출력한다. 문자열은 따옴표로 감싸고(`\"Hello World\"`), 숫자는 따옴표 없이 쓴다(`42`). 계산식을 직접 넣으면 결과가 출력된다(`console.log(10 + 5)` → 15)."},{"h":"변수로 계산","t":"`const city = \"Seoul\"`처럼 값을 변수에 담아 재사용한다. 곱셈 `*`, 덧셈 `+`을 쓰고, 문자열끼리 `+`는 이어붙이기(`\"안녕\" + \"코딩\"` → \"안녕코딩\"). 단가×개수 같은 계산도 변수로 표현한다."}],"code":{"c":"console.log(\"Hello World\");\nconsole.log(42);\nconst a = 7, b = 3;\nconsole.log(a * b);        // 21\nconsole.log(\"안녕\" + \"코딩\");  // 안녕코딩","cap":"문자열은 따옴표로, 숫자는 그대로, +는 문자열 이어붙이기."},"key":["console.log(값)으로 출력","문자열은 따옴표, 숫자는 따옴표 없이","숫자 +는 덧셈, 문자열 +는 이어붙이기","변수에 값을 담아 재사용"]}},{"t":"변수로 계산하기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"a=7, b=3 일 때 a 곱하기 b (21) 를 출력하세요.","src":"let a = 7;\nlet b = 3;\nconsole.log();","expect":"21","ex":"console.log(a * b);"},{"t":"code","k":"코딩 과제","run":"js","q":"\"안녕\" 과 \"코딩\" 을 이어붙여 안녕코딩 을 출력하세요.","src":"console.log(\"안녕\" + );","expect":"안녕코딩","ex":"문자열 + 로 이어붙여요: \"안녕\" + \"코딩\"."},{"t":"code","k":"코딩 과제","run":"js","q":"가격 1000원짜리 3개의 총액(3000)을 출력하세요.","src":"let price = 1000;\nlet count = 3;\nconsole.log();","expect":"3000","ex":"console.log(price * count);"}],"th":{"sum":"**출력과 변수** 첫걸음. `console.log`로 값과 계산 결과를 출력하고 변수에 저장한다.","body":[{"h":"변수로 계산","t":"`const city = \"Seoul\"`처럼 값을 변수에 담아 재사용한다. 곱셈 `*`, 덧셈 `+`을 쓰고, 문자열끼리 `+`는 이어붙이기(`\"안녕\" + \"코딩\"` → \"안녕코딩\"). 단가×개수 같은 계산도 변수로 표현한다."},{"h":"출력하기","t":"`console.log(값)`으로 화면에 출력한다. 문자열은 따옴표로 감싸고(`\"Hello World\"`), 숫자는 따옴표 없이 쓴다(`42`). 계산식을 직접 넣으면 결과가 출력된다(`console.log(10 + 5)` → 15)."}],"code":{"c":"console.log(\"Hello World\");\nconsole.log(42);\nconst a = 7, b = 3;\nconsole.log(a * b);        // 21\nconsole.log(\"안녕\" + \"코딩\");  // 안녕코딩","cap":"문자열은 따옴표로, 숫자는 그대로, +는 문자열 이어붙이기."},"key":["console.log(값)으로 출력","문자열은 따옴표, 숫자는 따옴표 없이","숫자 +는 덧셈, 문자열 +는 이어붙이기","변수에 값을 담아 재사용"]}}]},{"t":"조건과 반복 (직접 짜기)","l":[{"t":"조건문 완성하기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"x 가 10 이상이면 \"크다\" 를 출력하도록 조건을 완성하세요.","src":"let x = 10;\nif (x >= ) {\n  console.log(\"크다\");\n}","expect":"크다","ex":"if (x >= 10) 으로 비교하세요."},{"t":"code","k":"코딩 과제","run":"js","q":"점수 45 가 60 미만이면 \"불합격\" 을 출력하세요.","src":"let score = 45;\nif ( ) {\n  console.log(\"불합격\");\n}","expect":"불합격","ex":"if (score < 60) 로 비교하세요."},{"t":"code","k":"코딩 과제","run":"js","q":"n=4 가 짝수이면 \"짝수\" 를 출력하세요.","src":"let n = 4;\nif (n % 2 === 0) {\n  console.log();\n}","expect":"짝수","ex":"console.log(\"짝수\");"}],"th":{"sum":"**조건문(if)과 반복문(for)** 첫걸음. 비교로 분기하고, 반복으로 여러 번 실행·누적한다.","body":[{"h":"조건문","t":"`if (조건) { ... }`으로 조건이 참일 때만 실행한다. 비교 연산자는 `>=`(이상), `<`(미만), 짝수는 `n % 2 === 0`. 예: `if (x >= 10) console.log(\"크다\")`."},{"h":"반복문","t":"`for (let i = 1; i <= 5; i++)`로 1부터 5까지 반복한다. 합계는 루프 밖 변수에 `sum += i`로 누적. 짝수만 출력하려면 조건(`i % 2 === 0`)을 걸거나 `i += 2`로 건너뛴다."}],"code":{"c":"for (let i = 1; i <= 5; i++) {\n  console.log(i);\n}\n\nlet sum = 0;\nfor (let i = 1; i <= 10; i++) sum += i;\nconsole.log(sum);  // 55","cap":"for로 1~5 출력, 누적 변수로 1~10 합 55."},"key":["if (조건)은 참일 때만 실행","짝수 판별 = n % 2 === 0","for로 시작~끝 반복","합계는 루프 밖 변수에 += 누적"]}},{"t":"반복문 완성하기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"1부터 5까지 한 줄씩 출력하세요.","src":"for (let i = 1; i <= ; i++) {\n  console.log(i);\n}","expect":"12345","ex":"i <= 5 까지 반복하세요."},{"t":"code","k":"코딩 과제","run":"js","q":"\"별\" 을 4번 출력하세요.","src":"for (let i = 0; i < 4; i++) {\n  console.log();\n}","expect":"별별별별","ex":"console.log(\"별\");"},{"t":"code","k":"코딩 과제","run":"js","q":"1부터 10까지 더한 합(55)을 출력하세요.","src":"let sum = 0;\nfor (let i = 1; i <= 10; i++) {\n  sum = sum + i;\n}\nconsole.log();","expect":"55","ex":"console.log(sum);"},{"t":"code","k":"코딩 과제","run":"js","q":"2, 4, 6, 8, 10 (짝수)만 출력하세요.","src":"for (let i = 2; i <= 10; i = i + ) {\n  console.log(i);\n}","expect":"246810","ex":"i = i + 2 로 2씩 증가시켜요."}],"th":{"sum":"**조건문(if)과 반복문(for)** 첫걸음. 비교로 분기하고, 반복으로 여러 번 실행·누적한다.","body":[{"h":"조건문","t":"`if (조건) { ... }`으로 조건이 참일 때만 실행한다. 비교 연산자는 `>=`(이상), `<`(미만), 짝수는 `n % 2 === 0`. 예: `if (x >= 10) console.log(\"크다\")`."},{"h":"반복문","t":"`for (let i = 1; i <= 5; i++)`로 1부터 5까지 반복한다. 합계는 루프 밖 변수에 `sum += i`로 누적. 짝수만 출력하려면 조건(`i % 2 === 0`)을 걸거나 `i += 2`로 건너뛴다."}],"code":{"c":"for (let i = 1; i <= 5; i++) {\n  console.log(i);\n}\n\nlet sum = 0;\nfor (let i = 1; i <= 10; i++) sum += i;\nconsole.log(sum);  // 55","cap":"for로 1~5 출력, 누적 변수로 1~10 합 55."},"key":["if (조건)은 참일 때만 실행","짝수 판별 = n % 2 === 0","for로 시작~끝 반복","합계는 루프 밖 변수에 += 누적"]}}]},{"t":"함수와 배열 (직접 짜기)","l":[{"t":"함수 완성하기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"두 수를 더해 돌려주는 함수 add 를 완성하고 add(3,4) 를 출력하세요.","src":"function add(a, b) {\n  return ;\n}\nconsole.log(add(3, 4));","expect":"7","ex":"return a + b;"},{"t":"code","k":"코딩 과제","run":"js","q":"숫자를 제곱해 돌려주는 함수 square 를 완성하고 square(6) 을 출력하세요.","src":"function square(n) {\n  return ;\n}\nconsole.log(square(6));","expect":"36","ex":"return n * n;"},{"t":"code","k":"코딩 과제","run":"js","q":"아래 greet 함수를 실행해서 결과를 확인하세요. (그대로 실행!)","src":"function greet(name) {\n  return \"안녕, \" + name + \"!\";\n}\nconsole.log(greet(\"민수\"));","expect":"안녕, 민수!","ex":"함수가 인사말을 만들어 돌려줘요."}],"th":{"sum":"**함수 정의와 배열 다루기** 첫걸음. 함수로 값을 반환하고, 배열 인덱스·순회·필터를 익힌다.","body":[{"h":"함수 완성","t":"`function add(a, b) { return a + b; }`처럼 정의하고 `add(3, 4)`로 호출한다. `return`으로 결과를 돌려줘야 값을 쓸 수 있다. 제곱은 `x * x`를 반환. 정의한 함수는 호출해야 실제로 실행된다."},{"h":"배열 다루기","t":"인덱스는 0부터: `[10,20,30][0]`은 10. 합은 for로 순회하며 누적. 필터는 조건에 맞는 값만 남긴다(`arr.filter(x => x > 3)`). 길이는 `arr.length`."}],"code":{"c":"function add(a, b) {\n  return a + b;\n}\nconsole.log(add(3, 4));  // 7\n\nconst nums = [5, 10, 15];\nlet sum = 0;\nfor (const x of nums) sum += x;\nconsole.log(sum);  // 30","cap":"함수는 return으로 값을 돌려주고, for로 배열을 순회·누적."},"key":["함수는 return으로 결과 반환","배열 인덱스는 0부터","합계는 for 순회 + 누적","filter는 조건에 맞는 값만 남김"]}},{"t":"배열 다루기","q":[{"t":"code","k":"코딩 과제","run":"js","q":"배열 [10, 20, 30] 의 첫 번째 값(10)을 출력하세요.","src":"let arr = [10, 20, 30];\nconsole.log(arr[]);","expect":"10","ex":"인덱스는 0부터! arr[0]."},{"t":"code","k":"코딩 과제","run":"js","q":"배열 [5, 10, 15] 의 합(30)을 반복문으로 구해 출력하세요. (그대로 실행!)","src":"let arr = [5, 10, 15];\nlet sum = 0;\nfor (let i = 0; i < arr.length; i++) {\n  sum = sum + arr[i];\n}\nconsole.log(sum);","expect":"30","ex":"각 원소를 더하면 30이에요."},{"t":"code","k":"코딩 과제","run":"js","q":"배열 [1,2,3,4,5] 에서 3보다 큰 수만 걸러 출력하세요. (결과 [4,5])","src":"let arr = [1, 2, 3, 4, 5];\nlet big = arr.filter(function(x) {\n  return x > ;\n});\nconsole.log(big);","expect":"[4,5]","ex":"return x > 3;"},{"t":"code","k":"코딩 과제","run":"js","q":"배열 [3, 1, 2] 의 길이(3)를 출력하세요.","src":"let arr = [3, 1, 2];\nconsole.log(arr.);","expect":"3","ex":"arr.length 로 개수를 구해요."}],"th":{"sum":"**함수 정의와 배열 다루기** 첫걸음. 함수로 값을 반환하고, 배열 인덱스·순회·필터를 익힌다.","body":[{"h":"배열 다루기","t":"인덱스는 0부터: `[10,20,30][0]`은 10. 합은 for로 순회하며 누적. 필터는 조건에 맞는 값만 남긴다(`arr.filter(x => x > 3)`). 길이는 `arr.length`."},{"h":"함수 완성","t":"`function add(a, b) { return a + b; }`처럼 정의하고 `add(3, 4)`로 호출한다. `return`으로 결과를 돌려줘야 값을 쓸 수 있다. 제곱은 `x * x`를 반환. 정의한 함수는 호출해야 실제로 실행된다."}],"code":{"c":"function add(a, b) {\n  return a + b;\n}\nconsole.log(add(3, 4));  // 7\n\nconst nums = [5, 10, 15];\nlet sum = 0;\nfor (const x of nums) sum += x;\nconsole.log(sum);  // 30","cap":"함수는 return으로 값을 돌려주고, for로 배열을 순회·누적."},"key":["함수는 return으로 결과 반환","배열 인덱스는 0부터","합계는 for 순회 + 누적","filter는 조건에 맞는 값만 남김"]}}]},{"t":"표를 다루는 법 — 정렬·검증·집계","g":"📊","l":[{"t":"데이터 다루기 I","q":[{"t":"code","run":"js","k":"code-sortby","q":"객체 배열을 주어진 키의 값 오름차순으로 정렬한 <b>새 배열</b>을 돌려주는 <code>sortBy(rows, key)</code> 를 구현하세요. <b>원본은 그대로여야</b> 하고, 숫자는 숫자 크기대로 정렬돼야 합니다.","src":"function sortBy(rows, key){\n  // TODO\n  \n}","tests":[{"in":"sortBy([{n:'b'},{n:'a'},{n:'c'}],'n').map(r=>r.n)","out":"['a','b','c']"},{"in":"sortBy([{v:10},{v:9},{v:100}],'v').map(r=>r.v)","out":"[9,10,100]"},{"in":"(function(){const s=[{v:2},{v:1}]; sortBy(s,'v'); return s.map(r=>r.v);})()","out":"[2,1]"},{"in":"sortBy([{v:1}],'v').map(r=>r.v)","out":"[1]"}],"edge":[{"in":"sortBy([],'v')","out":"[]"}],"ex":"정렬에서 가장 자주 나오는 두 가지 실수를 한 번에 다룬다.\n💡 개념: <code>sort()</code> 는 비교 함수를 안 주면 값을 문자열로 바꿔 비교해서 <code>[10, 9, 100]</code> 이 <code>[10, 100, 9]</code> 가 된다. 그리고 <code>sort()</code> 는 원본 배열을 그 자리에서 바꾸므로, 원본을 지켜야 하면 <code>[...rows]</code> 로 먼저 복사해야 한다.\n🛠 실무: 화면에 정렬해 보여 주면서 원본 목록도 유지해야 하는 경우가 대부분이라 복사는 거의 기본이다. 숫자만 다룬다면 <code>(a, b) => a[key] - b[key]</code> 가 짧지만, 문자열도 들어올 수 있으면 위처럼 크기 비교로 쓰는 편이 안전하다."},{"t":"code","run":"js","k":"code-sortmulti","q":"여러 키로 차례로 정렬하는 <code>sortByMulti(rows, keys)</code> 를 구현하세요. 앞 키의 값이 <b>같을 때만</b> 다음 키를 봅니다. 원본은 그대로 두세요.","src":"function sortByMulti(rows, keys){\n  // TODO\n  \n}","tests":[{"in":"sortByMulti([{t:'b',s:1},{t:'a',s:2},{t:'a',s:1}],['t','s']).map(r=>r.t+r.s)","out":"['a1','a2','b1']"},{"in":"sortByMulti([{a:1,b:3},{a:1,b:2}],['a','b']).map(r=>r.b)","out":"[2,3]"},{"in":"sortByMulti([{a:2},{a:1}],['a']).map(r=>r.a)","out":"[1,2]"},{"in":"(function(){const s=[{a:2},{a:1}]; sortByMulti(s,['a']); return s.map(r=>r.a);})()","out":"[2,1]"}],"edge":[{"in":"sortByMulti([{a:1},{a:1}],['a']).length","out":"2"}],"ex":"'같으면 다음 기준' 이라는 규칙을 비교 함수 하나로 표현하는 연습이다.\n💡 개념: 비교 함수는 음수·0·양수 중 하나를 돌려주면 된다. 키를 순서대로 보다가 <b>차이가 나는 순간 결론을 내고</b>, 끝까지 같으면 0 을 돌려준다. 0 을 돌려주면 두 원소의 원래 순서가 유지된다.\n🛠 실무: 표 헤더를 눌러 정렬하는 화면에서 '부서 → 이름' 처럼 여러 기준을 쓰는 일이 흔하다. 방향까지 다루려면 키마다 오름/내림을 함께 받아 <code>-1</code> 을 곱하는 식으로 확장한다."},{"t":"code","run":"js","k":"code-topn","q":"값이 큰 순으로 상위 <code>n</code> 개를 돌려주는 <code>topN(rows, key, n)</code> 을 구현하세요. 원소가 <code>n</code> 개보다 적으면 있는 만큼만 돌려주고, 원본은 그대로 두세요.","src":"function topN(rows, key, n){\n  // TODO\n  \n}","tests":[{"in":"topN([{v:1},{v:5},{v:3}],'v',2).map(r=>r.v)","out":"[5,3]"},{"in":"topN([{v:1}],'v',3).map(r=>r.v)","out":"[1]"},{"in":"topN([{v:2},{v:2},{v:1}],'v',2).length","out":"2"},{"in":"topN([{v:1},{v:2}],'v',0)","out":"[]"}],"edge":[{"in":"topN([],'v',3)","out":"[]"}],"ex":"내림차순 정렬과 자르기를 붙이면 끝나지만, 경계에서 조용히 틀리기 쉽다.\n💡 개념: 내림차순은 비교 함수의 두 인자를 뒤집어 <code>b[key] - a[key]</code> 로 만든다. <code>slice(0, n)</code> 은 배열이 <code>n</code> 보다 짧아도, <code>n</code> 이 0 이어도 알아서 맞는 만큼만 잘라 준다 — 그래서 길이를 따로 검사할 필요가 없다.\n🛠 실무: '인기 상품 5개' 같은 화면의 기본형이다. 데이터가 아주 크면 전체를 정렬하는 대신 상위 n 개만 유지하며 한 번 훑는 방법이 더 빠르지만, 수천 건 수준에서는 정렬이 충분히 빠르고 읽기 쉽다."},{"t":"code","run":"js","k":"code-rank","q":"점수가 높은 순으로 줄 세운 뒤 <b>등수 배열</b>을 돌려주는 <code>rankOf(rows, key)</code> 를 구현하세요. <b>동점이면 같은 등수</b>이고, 그다음 등수는 인원수만큼 건너뜁니다(90·80·80·70 → 1·2·2·4).","src":"function rankOf(rows, key){\n  // TODO\n  \n}","tests":[{"in":"rankOf([{s:90},{s:80},{s:80},{s:70}],'s')","out":"[1,2,2,4]"},{"in":"rankOf([{s:1},{s:2}],'s')","out":"[1,2]"},{"in":"rankOf([{s:5},{s:5},{s:5}],'s')","out":"[1,1,1]"},{"in":"rankOf([{s:3}],'s')","out":"[1]"}],"edge":[{"in":"rankOf([],'s')","out":"[]"}],"ex":"'동점 처리' 는 규칙을 먼저 못 박지 않으면 반드시 틀린다.\n💡 개념: 정렬된 자리 번호를 그대로 등수로 쓰면 동점자가 다른 등수를 받는다. 앞 사람과 점수가 같으면 <b>앞 사람의 등수를 그대로</b> 쓰고, 다르면 <b>지금 자리 번호</b>를 새 등수로 삼는다. 그래서 2등이 둘이면 다음은 4등이 된다.\n🛠 실무: 등수 규칙은 하나가 아니다 — 여기 쓴 방식 말고 '2등이 둘이어도 다음은 3등' 인 방식도 흔하다. 어느 쪽인지 먼저 확인하고 시작한다."}],"th":{"sum":"지금까지 짠 함수들은 값 하나를 다뤘습니다. 실무에서 만나는 것은 대개 <b>줄과 칸이 있는 표</b>예요 — 주문 목록, 사용자 목록, 로그 행. 표를 다루는 일은 사실 <b>줄 세우기 · 걸러내기 · 묶기</b> 세 가지의 조합입니다.","body":[{"h":"정렬은 '비교하는 법' 을 넘겨주는 일","t":"<code>sort()</code> 를 그냥 부르면 값을 <b>문자열로 바꿔 비교</b>해서 <code>10</code> 이 <code>9</code> 앞에 옵니다. 무엇을 기준으로 어느 쪽이 앞인지는 <b>비교 함수</b>가 정해요. 그리고 <code>sort()</code> 는 <b>원본을 그 자리에서 바꾸므로</b>, 원본을 지켜야 한다면 먼저 복사해야 합니다."},{"h":"빈 값과 0 은 다르다","t":"값을 걸러 낼 때 <code>if (v)</code> 라고 쓰면 <b><code>0</code> 과 <code>false</code> 와 빈 문자열이 함께 사라집니다</b>. 수량 0 이나 '사용 안 함' 같은 값은 <b>있는 값</b>이에요. 무엇을 없는 값으로 볼지는 직접 정해서 명시적으로 비교해야 합니다."},{"h":"묶기는 결국 하나의 형태다","t":"개수 세기, 합계 내기, 목록으로 묶기 — 셋 다 <b>'키를 정하고, 그 키의 자리에 무언가를 쌓는다'</b> 는 같은 모양입니다. 쌓는 것이 숫자면 집계, 배열이면 그룹핑이 되는 것뿐이에요. 이 형태가 손에 익으면 새 요구가 와도 바꿀 부분이 한 줄입니다."}],"code":{"t":"표를 다루는 세 가지 동작","c":"줄 세우기   [...rows].sort((a, b) => a.v - b.v)     ← 복사 후 비교 함수\n걸러내기    rows.filter(r => r.v !== null)           ← 0 을 지우지 않게\n묶기        rows.reduce((out, r) => {\n              const k = r.type;\n              out[k] = (out[k] || 0) + 1;            ← 숫자면 집계\n              return out;\n            }, {})\n\n원본을 지켜야 하면 언제나 먼저 복사한다\n    sort · reverse · splice  → 원본을 바꾼다\n    map · filter · slice     → 새 배열을 만든다"},"key":["sort 는 원본을 바꾼다 — 지켜야 하면 먼저 복사한다","비교 함수를 안 주면 문자열로 비교돼 10 이 9 앞에 온다","빈 값을 거를 때 0 과 false 를 함께 지우지 않게 한다","개수·합계·그룹은 모두 '키에 쌓기' 라는 같은 모양이다"]}},{"t":"데이터 다루기 II","q":[{"t":"code","run":"js","k":"code-compact","q":"객체에서 값이 <code>null</code>·<code>undefined</code>·빈 문자열인 키를 제거한 새 객체를 돌려주는 <code>compact(obj)</code> 를 구현하세요. <b><code>0</code> 과 <code>false</code> 는 남겨야</b> 합니다.","src":"function compact(obj){\n  // TODO\n  \n}","tests":[{"in":"compact({a:1,b:null,c:'',d:undefined})","out":"{a:1}"},{"in":"compact({a:0,b:false})","out":"{a:0,b:false}"},{"in":"compact({a:'x',b:'  '})","out":"{a:'x',b:'  '}"},{"in":"compact({a:null})","out":"{}"}],"edge":[{"in":"compact({})","out":"{}"}],"ex":"<code>if (v)</code> 한 글자 차이로 0 이 사라진다.\n💡 개념: 자바스크립트에서 <code>0</code>·<code>false</code>·<code>''</code>·<code>null</code>·<code>undefined</code>·<code>NaN</code> 은 모두 조건문에서 거짓으로 취급된다. 그래서 <code>if (v) out[k] = v;</code> 라고 쓰면 수량 0 이나 '알림 끔(false)' 같은 <b>멀쩡한 값이 함께 지워진다</b>. 무엇을 없는 값으로 볼지 직접 비교해야 한다.\n🛠 실무: 폼에서 안 채운 항목만 빼고 서버로 보낼 때 자주 쓴다. 공백만 있는 문자열도 비울지는 요구에 따라 다르므로 여기서는 남겼다 — 지워야 한다면 비교 전에 <code>trim()</code> 한 값을 본다."},{"t":"code","run":"js","k":"code-validate","q":"검사 규칙을 통과하지 못한 <b>키 이름 배열</b>을 돌려주는 <code>validate(obj, rules)</code> 를 구현하세요. <code>rules</code> 는 <code>{키: 검사함수}</code> 이고, 검사 함수가 참이 아닌 값을 돌려주면 실패입니다. 순서는 <code>rules</code> 의 키 순서를 따릅니다.","src":"function validate(obj, rules){\n  // TODO\n  \n}","tests":[{"in":"validate({age:5},{age:v=>v>10})","out":"['age']"},{"in":"validate({a:1,b:2},{a:v=>v>0,b:v=>v>5})","out":"['b']"},{"in":"validate({a:1},{a:v=>v>0})","out":"[]"},{"in":"validate({},{name:v=>!!v})","out":"['name']"}],"edge":[{"in":"validate({},{})","out":"[]"}],"ex":"검사 규칙을 <b>데이터로</b> 넘기면 검증 로직이 한 줄이 된다.\n💡 개념: 규칙마다 <code>if</code> 를 쓰면 필드가 늘 때마다 코드가 늘어난다. 규칙을 <code>{키: 함수}</code> 객체로 받으면 검증하는 쪽은 '키를 돌며 함수를 불러 실패한 것만 모으는' 일만 하면 된다 — 필드가 늘어도 이 함수는 그대로다.\n🛠 실무: 키가 아예 없으면 <code>obj[k]</code> 가 <code>undefined</code> 로 넘어가므로 필수 여부도 같은 규칙으로 표현된다. 실제 폼에서는 키 이름 대신 <b>사람이 읽을 오류 메시지</b>도 함께 돌려주도록 확장한다."},{"t":"code","run":"js","k":"code-parseint","q":"문자열 <b>전체</b>가 정수일 때만 숫자로 바꿔 돌려주고, 아니면 <code>null</code> 을 돌려주는 <code>parseIntStrict(s)</code> 를 구현하세요. 앞뒤 공백과 부호는 허용합니다.","src":"function parseIntStrict(s){\n  // TODO\n  \n}","tests":[{"in":"parseIntStrict('42')","out":"42"},{"in":"parseIntStrict(' -7 ')","out":"-7"},{"in":"parseIntStrict('12abc')","out":"null"},{"in":"parseIntStrict('3.5')","out":"null"}],"edge":[{"in":"parseIntStrict('')","out":"null"}],"ex":"<code>parseInt</code> 는 '읽을 수 있는 데까지' 읽고 멈춘다 — 검증용이 아니다.\n💡 개념: <code>parseInt('12abc')</code> 는 <code>12</code> 를 돌려준다. 사용자 입력을 검사할 때 이러면 <b>오타가 조용히 통과</b>한다. 전체가 정수인지 보려면 문자열 전체를 규칙에 맞춰 보고, 통과할 때만 숫자로 바꾼다.\n🛠 실무: <code>Number('')</code> 가 <code>0</code> 이고 <code>Number(' ')</code> 도 <code>0</code> 이라 그것만으로도 부족하다. 정규식의 <code>^</code> 와 <code>$</code> 가 '처음부터 끝까지' 를 뜻하는 것이 여기서 핵심이다."},{"t":"code","run":"js","k":"code-changed","q":"수정 전후 객체를 비교해 <b>값이 달라진 키 이름 배열</b>을 돌려주는 <code>changedKeys(before, after)</code> 를 구현하세요. <code>after</code> 에만 새로 생긴 키도 바뀐 것으로 봅니다. 순서는 <code>after</code> 의 키 순서를 따릅니다.","src":"function changedKeys(before, after){\n  // TODO\n  \n}","tests":[{"in":"changedKeys({a:1,b:2},{a:1,b:3})","out":"['b']"},{"in":"changedKeys({a:1},{a:1,b:2})","out":"['b']"},{"in":"changedKeys({a:1},{a:1})","out":"[]"},{"in":"changedKeys({a:1,b:2},{a:9,b:8})","out":"['a','b']"}],"edge":[{"in":"changedKeys({},{})","out":"[]"}],"ex":"'바뀐 것만 서버로 보내기' 의 핵심 한 줄.\n💡 개념: <code>after</code> 의 키를 돌면서 <code>before</code> 의 같은 키와 견주면 된다. <code>before</code> 에 없는 키는 <code>undefined</code> 가 나오므로 자연히 '달라짐' 으로 잡힌다.\n🛠 실무: 값이 객체나 배열이면 <code>!==</code> 는 <b>내용이 같아도 다르다고</b> 한다(참조 비교). 중첩 값까지 비교하려면 값을 문자열로 바꿔 견주거나 깊은 비교를 써야 한다. 그리고 <code>after</code> 에서 <b>사라진 키</b>는 이 방식으로 못 잡으니, 삭제도 다뤄야 한다면 양쪽 키를 합쳐 돈다."}],"th":{"sum":"지금까지 짠 함수들은 값 하나를 다뤘습니다. 실무에서 만나는 것은 대개 <b>줄과 칸이 있는 표</b>예요 — 주문 목록, 사용자 목록, 로그 행. 표를 다루는 일은 사실 <b>줄 세우기 · 걸러내기 · 묶기</b> 세 가지의 조합입니다.","body":[{"h":"정렬은 '비교하는 법' 을 넘겨주는 일","t":"<code>sort()</code> 를 그냥 부르면 값을 <b>문자열로 바꿔 비교</b>해서 <code>10</code> 이 <code>9</code> 앞에 옵니다. 무엇을 기준으로 어느 쪽이 앞인지는 <b>비교 함수</b>가 정해요. 그리고 <code>sort()</code> 는 <b>원본을 그 자리에서 바꾸므로</b>, 원본을 지켜야 한다면 먼저 복사해야 합니다."},{"h":"빈 값과 0 은 다르다","t":"값을 걸러 낼 때 <code>if (v)</code> 라고 쓰면 <b><code>0</code> 과 <code>false</code> 와 빈 문자열이 함께 사라집니다</b>. 수량 0 이나 '사용 안 함' 같은 값은 <b>있는 값</b>이에요. 무엇을 없는 값으로 볼지는 직접 정해서 명시적으로 비교해야 합니다."},{"h":"묶기는 결국 하나의 형태다","t":"개수 세기, 합계 내기, 목록으로 묶기 — 셋 다 <b>'키를 정하고, 그 키의 자리에 무언가를 쌓는다'</b> 는 같은 모양입니다. 쌓는 것이 숫자면 집계, 배열이면 그룹핑이 되는 것뿐이에요. 이 형태가 손에 익으면 새 요구가 와도 바꿀 부분이 한 줄입니다."}],"code":{"t":"표를 다루는 세 가지 동작","c":"줄 세우기   [...rows].sort((a, b) => a.v - b.v)     ← 복사 후 비교 함수\n걸러내기    rows.filter(r => r.v !== null)           ← 0 을 지우지 않게\n묶기        rows.reduce((out, r) => {\n              const k = r.type;\n              out[k] = (out[k] || 0) + 1;            ← 숫자면 집계\n              return out;\n            }, {})\n\n원본을 지켜야 하면 언제나 먼저 복사한다\n    sort · reverse · splice  → 원본을 바꾼다\n    map · filter · slice     → 새 배열을 만든다"},"key":["sort 는 원본을 바꾼다 — 지켜야 하면 먼저 복사한다","비교 함수를 안 주면 문자열로 비교돼 10 이 9 앞에 온다","빈 값을 거를 때 0 과 false 를 함께 지우지 않게 한다","개수·합계·그룹은 모두 '키에 쌓기' 라는 같은 모양이다"]}},{"t":"데이터 다루기 III","q":[{"t":"code","run":"js","k":"code-groupby","q":"각 원소에서 <code>keyFn</code> 으로 키를 얻어 <b>키별 배열</b>로 묶은 객체를 돌려주는 <code>groupBy(items, keyFn)</code> 을 구현하세요. 키는 <b>처음 나타난 순서</b>로 담습니다.","src":"function groupBy(items, keyFn){\n  // TODO\n  \n}","tests":[{"in":"groupBy([1,2,3,4], n=>n%2===0?'even':'odd')","out":"{odd:[1,3],even:[2,4]}"},{"in":"groupBy(['a','bb','cc'], s=>s.length)","out":"{1:['a'],2:['bb','cc']}"},{"in":"groupBy([{t:'x'},{t:'x'}], r=>r.t).x.length","out":"2"},{"in":"Object.keys(groupBy(['b','a'], s=>s))","out":"['b','a']"}],"edge":[{"in":"groupBy([], x=>x)","out":"{}"}],"ex":"그룹핑·개수 세기·합계는 전부 이 모양의 변주다.\n💡 개념: '키를 정하고 그 자리에 쌓는다' 가 전부다. 쌓기 전에 그 자리가 비어 있으면 빈 배열을 먼저 놓아 주는 것이 유일한 요령이다. <code>out[k] = out[k] || []</code> 도 같은 뜻이다.\n🛠 실무: 키가 숫자처럼 생기면 객체는 <b>정수 키를 작은 값부터</b> 먼저 늘어놓는다 — 삽입 순서와 다를 수 있으니, 순서가 중요하면 <code>Map</code> 을 쓴다. 요즘은 <code>Object.groupBy</code> 가 있는 환경도 있지만, 직접 짜 보면 뒤이어 나오는 집계들이 전부 같은 틀임이 보인다."},{"t":"code","run":"js","k":"code-countby","q":"<code>keyFn</code> 으로 얻은 키별 <b>개수</b>를 담은 객체를 돌려주는 <code>countBy(items, keyFn)</code> 을 구현하세요.","src":"function countBy(items, keyFn){\n  // TODO\n  \n}","tests":[{"in":"countBy(['a','b','a'], s=>s)","out":"{a:2,b:1}"},{"in":"countBy([1,2,3], n=>n%2===0?'even':'odd')","out":"{odd:2,even:1}"},{"in":"countBy([{s:'ok'},{s:'no'},{s:'ok'}], r=>r.s)","out":"{ok:2,no:1}"},{"in":"countBy(['x'], s=>s)","out":"{x:1}"}],"edge":[{"in":"countBy([], s=>s)","out":"{}"}],"ex":"앞의 그룹핑에서 <b>쌓는 것만</b> 배열에서 숫자로 바꾸면 된다.\n💡 개념: <code>out[k] = (out[k] || 0) + 1</code> 한 줄이 핵심이다. 그 자리가 비어 있으면 0 에서 시작하고, 있으면 거기에 하나를 더한다. 그룹핑과 뼈대가 완전히 같다.\n🛠 실무: 로그에서 상태 코드별 건수, 응답에서 오류 유형별 건수를 세는 일이 늘 있다. 세어 놓고 값이 큰 순으로 보고 싶다면 <code>Object.entries(...)</code> 로 쌍 배열을 만든 뒤 정렬한다."},{"t":"code","run":"js","k":"code-sumby","q":"각 행에서 <code>key</code> 의 값을 더한 합을 돌려주는 <code>sumBy(rows, key)</code> 를 구현하세요. 값이 <b>숫자가 아닌 행은 건너뜁니다</b>.","src":"function sumBy(rows, key){\n  // TODO\n  \n}","tests":[{"in":"sumBy([{v:1},{v:2}],'v')","out":"3"},{"in":"sumBy([{v:1},{v:'x'},{v:2}],'v')","out":"3"},{"in":"sumBy([{a:1}],'v')","out":"0"},{"in":"sumBy([{v:-2},{v:5}],'v')","out":"3"}],"edge":[{"in":"sumBy([],'v')","out":"0"}],"ex":"합계에서 값 하나만 문자열이어도 결과가 통째로 망가진다.\n💡 개념: 자바스크립트에서 <code>1 + '2'</code> 는 <code>'12'</code> 다. 숫자와 문자열을 <code>+</code> 로 만나게 하면 <b>덧셈이 아니라 이어붙이기</b>가 된다. 그래서 한 행만 문자열이어도 그 뒤로 전부 문자열이 되어 버린다.\n🛠 실무: 서버나 CSV 에서 온 값은 숫자처럼 보여도 문자열인 경우가 흔하다. 건너뛸지, 숫자로 바꿀지, 오류로 볼지를 <b>먼저 정하고</b> 시작한다. 여기서는 건너뛰었지만 조용히 넘기는 것이 늘 옳지는 않다."},{"t":"code","run":"js","k":"code-indexby","q":"각 행의 <code>key</code> 값을 프로퍼티 이름으로 삼아 <b>행을 바로 찾을 수 있는 객체</b>를 만드는 <code>indexBy(rows, key)</code> 를 구현하세요. 같은 키가 여러 번 나오면 <b>마지막 행</b>이 남습니다.","src":"function indexBy(rows, key){\n  // TODO\n  \n}","tests":[{"in":"indexBy([{id:'a',v:1},{id:'b',v:2}],'id').b.v","out":"2"},{"in":"indexBy([{id:'a',v:1},{id:'a',v:9}],'id').a.v","out":"9"},{"in":"Object.keys(indexBy([{id:'x'},{id:'y'}],'id'))","out":"['x','y']"},{"in":"indexBy([{id:'a'}],'id').b","out":"undefined"}],"edge":[{"in":"indexBy([],'id')","out":"{}"}],"ex":"목록에서 <code>find</code> 를 반복하는 코드는 대개 이걸로 바뀐다.\n💡 개념: 배열에서 <code>find</code> 로 찾으면 매번 처음부터 훑는다. 행이 1,000개인 목록을 1,000번 찾으면 100만 번을 비교하는 셈이다. 한 번 훑어 키로 찾을 수 있는 객체를 만들어 두면 그다음부터는 바로 꺼낸다.\n🛠 실무: 두 목록을 짝지을 때 거의 항상 먼저 하는 준비 작업이다. 다만 <b>같은 키가 여러 개인지</b>를 반드시 확인한다 — 조용히 마지막 것만 남으면 데이터가 사라진 줄도 모른다."}],"th":{"sum":"지금까지 짠 함수들은 값 하나를 다뤘습니다. 실무에서 만나는 것은 대개 <b>줄과 칸이 있는 표</b>예요 — 주문 목록, 사용자 목록, 로그 행. 표를 다루는 일은 사실 <b>줄 세우기 · 걸러내기 · 묶기</b> 세 가지의 조합입니다.","body":[{"h":"정렬은 '비교하는 법' 을 넘겨주는 일","t":"<code>sort()</code> 를 그냥 부르면 값을 <b>문자열로 바꿔 비교</b>해서 <code>10</code> 이 <code>9</code> 앞에 옵니다. 무엇을 기준으로 어느 쪽이 앞인지는 <b>비교 함수</b>가 정해요. 그리고 <code>sort()</code> 는 <b>원본을 그 자리에서 바꾸므로</b>, 원본을 지켜야 한다면 먼저 복사해야 합니다."},{"h":"빈 값과 0 은 다르다","t":"값을 걸러 낼 때 <code>if (v)</code> 라고 쓰면 <b><code>0</code> 과 <code>false</code> 와 빈 문자열이 함께 사라집니다</b>. 수량 0 이나 '사용 안 함' 같은 값은 <b>있는 값</b>이에요. 무엇을 없는 값으로 볼지는 직접 정해서 명시적으로 비교해야 합니다."},{"h":"묶기는 결국 하나의 형태다","t":"개수 세기, 합계 내기, 목록으로 묶기 — 셋 다 <b>'키를 정하고, 그 키의 자리에 무언가를 쌓는다'</b> 는 같은 모양입니다. 쌓는 것이 숫자면 집계, 배열이면 그룹핑이 되는 것뿐이에요. 이 형태가 손에 익으면 새 요구가 와도 바꿀 부분이 한 줄입니다."}],"code":{"t":"표를 다루는 세 가지 동작","c":"줄 세우기   [...rows].sort((a, b) => a.v - b.v)     ← 복사 후 비교 함수\n걸러내기    rows.filter(r => r.v !== null)           ← 0 을 지우지 않게\n묶기        rows.reduce((out, r) => {\n              const k = r.type;\n              out[k] = (out[k] || 0) + 1;            ← 숫자면 집계\n              return out;\n            }, {})\n\n원본을 지켜야 하면 언제나 먼저 복사한다\n    sort · reverse · splice  → 원본을 바꾼다\n    map · filter · slice     → 새 배열을 만든다"},"key":["sort 는 원본을 바꾼다 — 지켜야 하면 먼저 복사한다","비교 함수를 안 주면 문자열로 비교돼 10 이 9 앞에 온다","빈 값을 거를 때 0 과 false 를 함께 지우지 않게 한다","개수·합계·그룹은 모두 '키에 쌓기' 라는 같은 모양이다"]}},{"t":"데이터 다루기 IV","q":[{"t":"code","run":"js","k":"code-joinon","q":"두 목록을 <code>key</code> 기준으로 짝지어 합치는 <code>joinOn(left, right, key)</code> 을 구현하세요. <b>왼쪽 목록이 기준</b>이고, 오른쪽에 짝이 있으면 그 필드를 덮어써 합치며, 없으면 왼쪽 행을 그대로 둡니다. 결과는 새 객체여야 합니다.","src":"function joinOn(left, right, key){\n  // TODO\n  \n}","tests":[{"in":"joinOn([{id:1,a:1}],[{id:1,b:2}],'id')","out":"[{id:1,a:1,b:2}]"},{"in":"joinOn([{id:1}],[{id:2}],'id')","out":"[{id:1}]"},{"in":"joinOn([{id:1,v:'L'}],[{id:1,v:'R'}],'id')[0].v","out":"'R'"},{"in":"(function(){const l=[{id:1}]; joinOn(l,[{id:1,b:2}],'id'); return l[0].b;})()","out":"undefined"}],"edge":[{"in":"joinOn([],[{id:1}],'id')","out":"[]"}],"ex":"SQL 의 LEFT JOIN 을 손으로 짜 보는 것.\n💡 개념: 왼쪽 행마다 오른쪽을 훑으면 두 목록 크기의 곱만큼 비교하게 된다. 오른쪽을 먼저 <b>키로 찾을 수 있는 형태</b>로 만들어 두면 왼쪽을 한 번 훑는 것으로 끝난다 — 앞에서 만든 <code>indexBy</code> 가 그대로 쓰인다.\n🛠 실무: <code>{ ...l, ...짝 }</code> 은 겹치는 키를 <b>오른쪽 값으로 덮어쓴다</b>. 어느 쪽이 이겨야 하는지 확인하고 순서를 정한다. 마지막 테스트처럼 <b>원본을 건드리지 않는지</b>도 함께 확인하는 습관을 들이면 좋다."},{"t":"code","run":"js","k":"code-paginate","q":"목록을 페이지 단위로 잘라 <code>{items, page, pages, total}</code> 을 돌려주는 <code>paginate(items, page, size)</code> 를 구현하세요. <code>page</code> 는 1부터 시작하고, 범위를 벗어난 페이지는 빈 배열을 돌려줍니다.","src":"function paginate(items, page, size){\n  // TODO\n  \n}","tests":[{"in":"paginate([1,2,3,4,5],1,2)","out":"{items:[1,2],page:1,pages:3,total:5}"},{"in":"paginate([1,2,3,4,5],3,2)","out":"{items:[5],page:3,pages:3,total:5}"},{"in":"paginate([1,2,3],9,2).items","out":"[]"},{"in":"paginate([1,2,3,4],2,2).items","out":"[3,4]"}],"edge":[{"in":"paginate([],1,2)","out":"{items:[],page:1,pages:0,total:0}"}],"ex":"1부터 세는 페이지 번호와 0부터 세는 배열 자리를 잇는 계산.\n💡 개념: <code>page</code> 가 1 일 때 잘라 낼 시작 자리는 0 이므로 <code>(page - 1) * size</code> 다. 여기서 <code>-1</code> 을 빠뜨리면 첫 페이지가 통째로 사라진다. 전체 페이지 수는 <code>Math.ceil</code> 로 <b>올림</b>해야 마지막 자투리 페이지가 포함된다.\n🛠 실무: <code>slice</code> 는 범위를 넘겨도 오류 없이 빈 배열을 주므로 페이지 검사를 따로 안 해도 안전하다. 다만 데이터가 계속 추가되는 목록에서는 이런 번호 방식이 중복·누락을 만드니, 기준점을 넘겨받는 방식을 쓴다."},{"t":"code","run":"js","k":"code-defaults","q":"각 행에 기본값을 채워 넣은 <b>새 배열</b>을 돌려주는 <code>fillDefaults(rows, defaults)</code> 를 구현하세요. 행에 <b>이미 있는 값이 우선</b>이고, 없는 키만 기본값으로 채웁니다. 원본 행은 건드리지 마세요.","src":"function fillDefaults(rows, defaults){\n  // TODO\n  \n}","tests":[{"in":"fillDefaults([{a:1}],{a:0,b:9})","out":"[{a:1,b:9}]"},{"in":"fillDefaults([{}],{x:1})","out":"[{x:1}]"},{"in":"fillDefaults([{a:1},{a:2}],{b:0}).map(r=>r.a)","out":"[1,2]"},{"in":"(function(){const r={a:1}; fillDefaults([r],{b:2}); return r.b;})()","out":"undefined"}],"edge":[{"in":"fillDefaults([],{a:1})","out":"[]"}],"ex":"펼치기 순서 하나로 '기본값' 이 되기도 '덮어쓰기' 가 되기도 한다.\n💡 개념: <code>{ ...defaults, ...r }</code> 은 기본값을 먼저 깔고 행의 값으로 <b>덮어쓴다</b> — 그래서 행에 있는 값이 이긴다. 순서를 뒤집으면 기본값이 행을 덮어써 원하는 것과 정반대가 된다.\n🛠 실무: 설정 병합, API 응답에 빠진 필드 채우기에 그대로 쓴다. 다만 이 방식은 <b>한 겹만</b> 채운다 — 중첩된 객체는 통째로 교체되므로, 안쪽까지 채우려면 재귀로 내려가야 한다."},{"t":"code","run":"js","k":"code-summarize","q":"숫자 열 하나를 요약해 <code>{count, min, max, avg}</code> 를 돌려주는 <code>summarize(rows, key)</code> 를 구현하세요. <b>숫자인 값만</b> 세고, 숫자가 하나도 없으면 <code>{count:0, min:null, max:null, avg:null}</code> 을 돌려줍니다.","src":"function summarize(rows, key){\n  // TODO\n  \n}","tests":[{"in":"summarize([{v:1},{v:3}],'v')","out":"{count:2,min:1,max:3,avg:2}"},{"in":"summarize([{v:5},{v:1},{v:3}],'v')","out":"{count:3,min:1,max:5,avg:3}"},{"in":"summarize([{v:2},{v:'x'}],'v')","out":"{count:1,min:2,max:2,avg:2}"},{"in":"summarize([{v:'x'}],'v')","out":"{count:0,min:null,max:null,avg:null}"}],"edge":[{"in":"summarize([],'v')","out":"{count:0,min:null,max:null,avg:null}"}],"ex":"빈 입력을 먼저 처리하지 않으면 조용히 이상한 값이 나온다.\n💡 개념: <code>Math.min()</code> 을 인자 없이 부르면 <code>Infinity</code> 가 나오고 <code>Math.max()</code> 는 <code>-Infinity</code> 가 나온다. 오류도 안 나고 그럴듯해 보이지도 않는 값이 화면까지 흘러간다. 그래서 <b>값이 하나도 없는 경우를 맨 앞에서 걸러</b> 낸다.\n🛠 실무: 평균은 0 으로 나누면 <code>NaN</code> 이 되고, <code>NaN</code> 은 계산을 거치는 족족 <code>NaN</code> 을 퍼뜨린다. 여기서는 <code>null</code> 로 정했지만 화면에 '—' 로 보여 줄지 0 으로 볼지는 요구에 따라 정하고, <b>정했다는 사실을 코드에 남긴다</b>."}],"th":{"sum":"지금까지 짠 함수들은 값 하나를 다뤘습니다. 실무에서 만나는 것은 대개 <b>줄과 칸이 있는 표</b>예요 — 주문 목록, 사용자 목록, 로그 행. 표를 다루는 일은 사실 <b>줄 세우기 · 걸러내기 · 묶기</b> 세 가지의 조합입니다.","body":[{"h":"정렬은 '비교하는 법' 을 넘겨주는 일","t":"<code>sort()</code> 를 그냥 부르면 값을 <b>문자열로 바꿔 비교</b>해서 <code>10</code> 이 <code>9</code> 앞에 옵니다. 무엇을 기준으로 어느 쪽이 앞인지는 <b>비교 함수</b>가 정해요. 그리고 <code>sort()</code> 는 <b>원본을 그 자리에서 바꾸므로</b>, 원본을 지켜야 한다면 먼저 복사해야 합니다."},{"h":"빈 값과 0 은 다르다","t":"값을 걸러 낼 때 <code>if (v)</code> 라고 쓰면 <b><code>0</code> 과 <code>false</code> 와 빈 문자열이 함께 사라집니다</b>. 수량 0 이나 '사용 안 함' 같은 값은 <b>있는 값</b>이에요. 무엇을 없는 값으로 볼지는 직접 정해서 명시적으로 비교해야 합니다."},{"h":"묶기는 결국 하나의 형태다","t":"개수 세기, 합계 내기, 목록으로 묶기 — 셋 다 <b>'키를 정하고, 그 키의 자리에 무언가를 쌓는다'</b> 는 같은 모양입니다. 쌓는 것이 숫자면 집계, 배열이면 그룹핑이 되는 것뿐이에요. 이 형태가 손에 익으면 새 요구가 와도 바꿀 부분이 한 줄입니다."}],"code":{"t":"표를 다루는 세 가지 동작","c":"줄 세우기   [...rows].sort((a, b) => a.v - b.v)     ← 복사 후 비교 함수\n걸러내기    rows.filter(r => r.v !== null)           ← 0 을 지우지 않게\n묶기        rows.reduce((out, r) => {\n              const k = r.type;\n              out[k] = (out[k] || 0) + 1;            ← 숫자면 집계\n              return out;\n            }, {})\n\n원본을 지켜야 하면 언제나 먼저 복사한다\n    sort · reverse · splice  → 원본을 바꾼다\n    map · filter · slice     → 새 배열을 만든다"},"key":["sort 는 원본을 바꾼다 — 지켜야 하면 먼저 복사한다","비교 함수를 안 주면 문자열로 비교돼 10 이 9 앞에 온다","빈 값을 거를 때 0 과 false 를 함께 지우지 않게 한다","개수·합계·그룹은 모두 '키에 쌓기' 라는 같은 모양이다"]}}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"변환 시뮬레이션","lv":2,"cat":"internals","q":"<code>map → filter → reduce</code> 파이프라인이 <b>단계마다 데이터를 어떻게 바꾸는지</b> 보이세요. 가격 목록에 부가세 10%를 붙이고(반올림), 1,000원 넘는 것만 남긴 뒤, 합계를 냅니다. 단계마다 <code>snap(단계, 그 단계의 결과, {count})</code> 를 남기고 <b>[중간 배열들의 길이 배열, 최종 합계, 원본이 그대로인지]</b> 를 돌려주세요.","src":"const PRICES = [500, 900, 1200, 3000, 700];\n\nfunction pipeline() {\n  return [[], 0, false];\n}\n\nRESULT = pipeline();","tests":[{"d":"map 은 개수를 유지하고 filter 가 5개를 2개로 줄인다","js":"JSON.stringify(RESULT[0])===JSON.stringify([5,5,2])"},{"d":"합계가 4,620","js":"RESULT[1]===4620"},{"d":"원본 배열은 바뀌지 않는다","js":"RESULT[2]===true"},{"d":"단계마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"부가세를 붙인 첫 값은 550","js":"FRAMES[0].value[0]===550"},{"d":"필터 뒤에는 1,000 이하가 남지 않는다","js":"FRAMES[1].value.every(function(v){return v>1000;})"}],"ex":"<code>map</code>·<code>filter</code> 는 <b>새 배열을 만들어 돌려주고 원본은 건드리지 않습니다</b> — 그래서 파이프라인으로 이어 붙여도 앞 단계의 데이터가 안전합니다. 대신 단계마다 <b>중간 배열이 하나씩 생기므로</b>, 아주 큰 배열에서는 한 번의 <code>reduce</code> 나 <code>for</code> 로 합치는 편이 메모리에 유리합니다(수천 개 수준에서는 가독성이 이깁니다). 함께 기억할 것은 <b>어떤 메서드가 원본을 바꾸는가</b> 입니다: <code>sort</code>·<code>reverse</code>·<code>splice</code>·<code>push</code> 는 원본을 바꾸고, <code>slice</code>·<code>concat</code>·<code>map</code>·<code>filter</code> 는 새것을 만듭니다. 이 구분을 놓치면 '분명 복사했는데 원본이 바뀐' 버그가 납니다."},{"t":"sim","k":"변환 시뮬레이션","lv":3,"cat":"internals","q":"설정 객체를 <b>얕게 병합</b>했을 때 무엇이 공유되는지 보이세요. <code>{...기본값, ...사용자값}</code> 은 <b>한 겹만</b> 복사하므로 중첩 객체는 <b>같은 것을 가리킵니다</b>. 각 단계마다 <code>snap(단계, {merged, base}, {shared})</code> 를 남기고 <b>[병합 결과의 theme, 중첩 값을 고친 뒤 기본값도 바뀌었는지, 깊은 복사로 했을 때 기본값이 바뀌었는지]</b> 를 돌려주세요.","src":"const DEFAULTS = { theme: 'light', retry: { count: 3, delay: 100 } };\nconst USER = { theme: 'dark' };\n\nfunction merge() {\n  return ['', false, false];\n}\n\nRESULT = merge();","tests":[{"d":"사용자 값이 기본값을 덮는다","js":"RESULT[0]==='dark'"},{"d":"얕은 병합에서는 중첩 값이 함께 바뀐다","js":"RESULT[1]===true"},{"d":"깊은 복사에서는 기본값이 지켜진다","js":"RESULT[2]===false"},{"d":"단계마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"병합 직후 중첩 객체는 같은 것을 가리킨다","js":"FRAMES[0].opt.shared===true"},{"d":"깊은 복사 뒤에는 공유가 끊긴다","js":"FRAMES[2].opt.shared===false"}],"ex":"전개 연산자와 <code>Object.assign</code> 은 <b>한 겹만</b> 복사합니다 — <code>retry</code> 같은 중첩 객체는 <b>주소만 복사</b>되어 병합 결과와 기본값이 같은 객체를 가리킵니다. 그래서 사용자 설정을 하나 고쳤을 뿐인데 <b>기본값 상수가 오염되고</b>, 다음 요청부터 이상하게 동작합니다. 특히 모듈 최상단의 <code>DEFAULTS</code> 처럼 <b>프로세스 내내 살아 있는 객체</b>가 오염되면 재현이 어렵습니다. 해법은 필요한 깊이만큼 명시적으로 복사하거나(<code>{...d, retry: {...d.retry, ...u.retry}}</code>), <code>structuredClone</code> 을 쓰거나, 애초에 <b>값을 바꾸지 않는 것</b>입니다."},{"t":"sim","k":"변환 시뮬레이션","lv":2,"cat":"internals","q":"주문 목록을 <b>고객별로 묶어</b> 합계를 내세요. 행을 하나씩 처리하며 <b>그 순간의 누적 상태</b>를 <code>snap('행 '+i, {...누적}, {key})</code> 로 남기고 <b>[고객 수, 가장 많이 쓴 고객, 그 금액, 처음 보는 고객이 등장한 횟수]</b> 를 돌려주세요. 동점이면 <b>먼저 나온 고객</b>이 이깁니다.","src":"const ORDERS = [\n  { user: 'kim', amount: 1000 },\n  { user: 'lee', amount: 2500 },\n  { user: 'kim', amount: 1500 },\n  { user: 'park', amount: 2000 },\n  { user: 'lee', amount: 500 },\n  { user: 'kim', amount: 500 }\n];\n\nfunction group() {\n  return [0, '', 0, 0];\n}\n\nRESULT = group();","tests":[{"d":"고객은 3명","js":"RESULT[0]===3"},{"d":"kim 이 3,000 으로 1위","js":"RESULT[1]==='kim'&&RESULT[2]===3000"},{"d":"처음 보는 고객이 3번 등장한다","js":"RESULT[3]===3"},{"d":"행마다 장면이 남는다","js":"FRAMES.length===6"},{"d":"세 번째 행에서 kim 이 2,500 이 된다","js":"FRAMES[2].value.kim===2500"},{"d":"동점 규칙 덕분에 lee(3,000) 가 아니라 kim 이 1위","js":"FRAMES[5].value.lee===3000&&RESULT[1]==='kim'"}],"ex":"그룹핑은 실무에서 가장 자주 쓰는 변환이고, 함정은 대개 <b>초기값</b>과 <b>동점 처리</b>입니다. <code>acc[key] = (acc[key] || 0) + v</code> 처럼 <b>없을 때의 기본값</b>을 챙기지 않으면 <code>undefined + 1 = NaN</code> 이 되어 조용히 망가집니다. 동점은 더 미묘합니다 — 여기서 kim 과 lee 는 둘 다 3,000 인데, '먼저 나온 쪽' 이라는 규칙을 정해 두지 않으면 <b>객체 순회 순서나 정렬 구현에 따라</b> 답이 달라집니다. 순위·1위 뽑기 같은 기능에서 '가끔 결과가 바뀐다' 는 신고가 들어오면 대개 여기가 원인입니다."},{"t":"sim","k":"정렬 시뮬레이션","lv":3,"cat":"internals","q":"<b>비교 함수</b>가 결과를 어떻게 바꾸는지 보이세요. 같은 배열을 <b>(1) 비교 함수 없이</b>, <b>(2) 숫자 비교로</b>, <b>(3) 점수 내림차순(동점은 원래 순서 유지)</b> 로 각각 정렬합니다. 방식마다 <code>snap(방식, 결과, {mode})</code> 를 남기고 <b>[비교 함수 없는 정렬 결과, 숫자 정렬 결과, 동점자 두 명의 이름 순서]</b> 를 돌려주세요.","src":"const NUMS = [10, 9, 100, 21];\nconst PLAYERS = [\n  { name: 'A', score: 50 },\n  { name: 'B', score: 70 },\n  { name: 'C', score: 50 }\n];\n\nfunction sorts() {\n  return [[], [], []];\n}\n\nRESULT = sorts();","tests":[{"d":"비교 함수가 없으면 문자열로 정렬된다","js":"JSON.stringify(RESULT[0])===JSON.stringify([10,100,21,9])"},{"d":"숫자 비교를 주면 제대로 정렬된다","js":"JSON.stringify(RESULT[1])===JSON.stringify([9,10,21,100])"},{"d":"동점자는 원래 순서를 지킨다(안정 정렬)","js":"JSON.stringify(RESULT[2])===JSON.stringify(['A','C'])"},{"d":"방식마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"문자열 정렬에서는 100 이 21 보다 앞","js":"FRAMES[0].value.indexOf(100)<FRAMES[0].value.indexOf(21)"},{"d":"점수 1위는 B","js":"FRAMES[2].value[0]==='B'"}],"ex":"<code>sort()</code> 는 기본적으로 원소를 <b>문자열로 바꿔</b> 비교합니다 — 그래서 <code>[10, 9, 100, 21]</code> 이 <code>[10, 100, 21, 9]</code> 가 됩니다. 숫자를 정렬할 때 <code>(a, b) =&gt; a - b</code> 를 반드시 주어야 하는 이유이고, 이 실수는 <b>한 자리 수만 넣어 테스트하면 드러나지 않습니다</b>. 두 번째로, 현대 자바스크립트의 <code>sort</code> 는 <b>안정</b>이라 동점이면 원래 순서가 보존됩니다(2019년 명세로 확정). 그래서 '점수 내림차순, 같으면 먼저 등록한 순' 같은 요구는 <b>두 번 정렬</b>하거나 비교 함수에 조건을 이어 붙여 표현할 수 있습니다. 마지막으로 <code>sort</code> 는 <b>원본을 바꿉니다</b> — 원본을 지키려면 <code>[...arr].sort()</code> 로 복사부터 하세요."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"문자열 시뮬레이션","lv":3,"cat":"internals","q":"문자열을 <b>이어 붙이는 방식</b>에 따른 작업량을 세세요. <code>+=</code> 로 붙이면 <b>매번 지금까지의 길이만큼</b>을 다시 쓰고, 배열에 모았다가 <code>join</code> 하면 <b>마지막에 한 번</b> 씁니다. 10조각마다 <code>snap(라벨, {concat, join}, {n})</code> 을 남기고 <b>[+= 방식이 쓴 글자 수, join 방식이 쓴 글자 수, 배수(내림)]</b> 를 돌려주세요. 조각은 각 5글자, 총 100개입니다.","src":"const PIECES = 100, LEN = 5;\n\nfunction build() {\n  return [0, 0, 0];\n}\n\nRESULT = build();","tests":[{"d":"+= 는 25,250자를 쓴다","js":"RESULT[0]===25250"},{"d":"join 은 500자만 쓴다","js":"RESULT[1]===500"},{"d":"50배 차이","js":"RESULT[2]===50"},{"d":"10조각마다 장면이 남는다","js":"FRAMES.length===10"},{"d":"+= 의 비용은 갈수록 가팔라진다","js":"FRAMES[9].value.concat-FRAMES[8].value.concat>FRAMES[1].value.concat-FRAMES[0].value.concat"},{"d":"join 의 비용은 일정하게 는다","js":"FRAMES[9].value.join-FRAMES[8].value.join===FRAMES[1].value.join-FRAMES[0].value.join"}],"ex":"문자열은 <b>불변</b>이라 <code>s += x</code> 는 '뒤에 덧붙이는' 것이 아니라 <b>새 문자열을 만들어 통째로 복사</b>하는 일입니다. 조각 수의 제곱으로 늘어나므로 100조각에 25,250자, 1,000조각이면 250만 자가 됩니다. 배열에 모아 <code>join</code> 하면 <b>필요한 만큼만</b> 한 번 씁니다. 다만 현실적인 조언을 덧붙이자면, <b>요즘 엔진은 짧은 반복의 <code>+=</code> 를 잘 최적화</b>하므로 몇십 개 수준에서는 차이를 못 느낍니다 — 문제는 로그·CSV·HTML 을 <b>수천 줄</b> 만들 때입니다. 그때는 배열에 모으거나 스트림으로 흘려보내세요."},{"t":"sim","k":"재귀 시뮬레이션","lv":3,"cat":"internals","q":"중첩된 폴더 구조를 <b>재귀로 훑어</b> 전체 크기를 구하세요. 들어갈 때와 나올 때마다 <code>snap(이름, {depth, total}, {phase})</code> 를 남기고 <b>[전체 크기, 최대 깊이, 방문한 노드 수]</b> 를 돌려주세요. 폴더의 크기는 <b>자기 파일들과 하위 폴더의 합</b>입니다.","src":"const TREE = {\n  name: 'root', size: 0, children: [\n    { name: 'src', size: 0, children: [\n      { name: 'a.js', size: 120, children: [] },\n      { name: 'lib', size: 0, children: [\n        { name: 'b.js', size: 300, children: [] }\n      ] }\n    ] },\n    { name: 'readme', size: 80, children: [] }\n  ]\n};\n\nfunction walk() {\n  return [0, 0, 0];\n}\n\nRESULT = walk();","tests":[{"d":"전체 크기가 500","js":"RESULT[0]===500"},{"d":"최대 깊이가 4","js":"RESULT[1]===4"},{"d":"노드 6개를 방문한다","js":"RESULT[2]===6"},{"d":"들어갈 때와 나올 때 모두 기록돼 장면이 12개","js":"FRAMES.length===12"},{"d":"가장 깊은 b.js 에서 깊이가 4","js":"FRAMES.some(function(f){return f.opt.depth===4;})"},{"d":"마지막 장면에서 합계가 완성된다","js":"FRAMES[11].value.total===500"}],"ex":"재귀는 <b>들어가는 길과 나오는 길</b>이 있다는 것을 눈으로 봐야 이해가 굳습니다 — 값이 완성되는 것은 <b>나오는 길</b>이고(자식의 합이 모여야 부모가 정해집니다), 그래서 장면이 노드 수의 두 배로 남습니다. 실무에서 이 구조를 만나는 곳은 폴더·댓글 트리·조직도·JSON 탐색입니다. 조심할 것 둘: <b>종료 조건</b>이 없거나 <b>순환 참조</b>(심볼릭 링크, 부모를 가리키는 필드)가 있으면 스택이 넘칩니다 — 방문한 노드를 <code>Set</code> 으로 기억하면 막을 수 있습니다. 그리고 깊이가 수만 단계로 갈 수 있다면 재귀 대신 <b>명시적 스택</b>으로 바꿔야 합니다."},{"t":"sim","k":"변환 시뮬레이션","lv":3,"cat":"internals","q":"중복을 없애는 <b>세 가지 방식</b>을 비교하세요. <b>(1) Set</b> 은 <b>값이 같은 원시값</b>만 합치고 객체는 <b>참조</b>로 구분합니다. <b>(2) JSON 문자열</b>을 키로 쓰면 내용이 같은 객체를 합치지만 <b>키 순서가 다르면</b> 다른 것으로 봅니다. <b>(3) 정해진 필드(id)</b>로 합치면 의도대로 됩니다. 방식마다 <code>snap(방식, 남은개수, {mode})</code> 를 남기고 <b>[Set 결과 개수, JSON 키 결과 개수, id 기준 결과 개수]</b> 를 돌려주세요.","src":"const ROWS = [\n  { id: 1, name: '가' },\n  { id: 1, name: '가' },          // 내용이 같은 다른 객체\n  { name: '가', id: 1 },          // 같은 내용, 키 순서만 다름\n  { id: 2, name: '나' }\n];\n\nfunction dedupe() {\n  return [0, 0, 0];\n}\n\nRESULT = dedupe();","tests":[{"d":"Set 은 객체를 참조로 봐서 4개 그대로","js":"RESULT[0]===4"},{"d":"JSON 키는 키 순서가 다른 것을 놓쳐 3개","js":"RESULT[1]===3"},{"d":"id 기준이면 의도대로 2개","js":"RESULT[2]===2"},{"d":"방식마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"뒤로 갈수록 잘 합쳐진다","js":"FRAMES[0].value>=FRAMES[1].value&&FRAMES[1].value>FRAMES[2].value"},{"d":"어떤 방식이었는지 기록된다","js":"FRAMES[2].opt.mode==='id'"}],"ex":"'중복' 이라는 말에는 <b>무엇을 같다고 볼 것인가</b> 라는 결정이 숨어 있습니다. <code>new Set(arr)</code> 은 원시값에는 완벽하지만 객체는 <b>참조가 같아야</b> 합치므로, 서버에서 두 번 받은 같은 내용의 객체는 전혀 합쳐지지 않습니다. <code>JSON.stringify</code> 를 키로 쓰는 흔한 우회는 <b>키 순서·undefined·Date</b> 에서 어긋나 조용히 실패합니다. 결국 옳은 방법은 <b>도메인이 정하는 식별자</b>(여기서는 <code>id</code>)로 합치는 것이고, 그래서 <code>Map</code> 에 <code>id</code> 를 키로 담는 관용구를 씁니다. API 응답을 합칠 때, 목록을 갱신할 때, 낙관적 업데이트를 되돌릴 때 모두 같은 원칙입니다."},{"t":"sim","k":"변환 시뮬레이션","lv":2,"cat":"internals","q":"목록을 <b>페이지로 자르세요</b>. 한 페이지는 4개이고 <code>slice((page-1)*4, page*4)</code> 로 자릅니다. 페이지마다 <code>snap('page '+p, 그 페이지의 항목, {from, to})</code> 를 남기고 <b>[전체 페이지 수, 마지막 페이지의 항목 수, 존재하지 않는 페이지를 요청했을 때의 항목 수, 1-based 를 0-based 로 착각했을 때 첫 페이지가 잃는 항목 수]</b> 를 돌려주세요. 항목은 10개입니다.","src":"const TOTAL = 10, PER = 4;\n\nfunction paginate() {\n  return [0, 0, 0, 0];\n}\n\nRESULT = paginate();","tests":[{"d":"10개를 4개씩 자르면 3페이지","js":"RESULT[0]===3"},{"d":"마지막 페이지에는 2개만 남는다","js":"RESULT[1]===2"},{"d":"없는 페이지는 빈 배열","js":"RESULT[2]===0"},{"d":"0-based 로 착각하면 첫 항목 4개를 건너뛴다","js":"RESULT[3]===4"},{"d":"페이지마다 장면이 남는다","js":"FRAMES.length===3"},{"d":"첫 페이지는 1번부터","js":"FRAMES[0].value[0]===1&&FRAMES[0].opt.from===0"},{"d":"페이지가 겹치지 않는다","js":"FRAMES[1].value[0]===5&&FRAMES[0].value[3]===4"}],"ex":"페이지네이션은 <b>경계에서만 틀리는</b> 코드의 대표입니다 — 가운데 페이지는 늘 맞고, 문제는 <b>첫 페이지·마지막 페이지·없는 페이지</b>에서 납니다. <code>slice</code> 는 끝 인덱스를 넘겨도 <b>있는 만큼만</b> 돌려주므로 마지막 페이지가 자연스럽게 처리되고, 범위를 벗어나면 <b>빈 배열</b>이라 오류가 나지 않습니다 — 편리하지만 그래서 <b>404 를 줘야 할 상황을 놓치기</b> 쉽습니다. 1-based 페이지 번호를 그대로 곱하는 실수(<code>page * PER</code>)도 흔한데, 첫 페이지가 통째로 사라져도 <b>2페이지부터는 멀쩡해 보입니다</b>. 그리고 목록이 계속 바뀌는 화면이라면 offset 방식 자체가 항목을 <b>건너뛰거나 중복해서</b> 보여 주므로, 커서 기반으로 바꾸는 편이 낫습니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"변환 시뮬레이션","lv":3,"cat":"internals","q":"겹치는 구간들을 <b>하나로 합치세요</b>. 규칙 — <b>시작점 기준으로 정렬</b>한 뒤 앞에서부터 훑으며, 다음 구간의 시작이 <b>지금 구간의 끝보다 작거나 같으면</b> 끝을 더 큰 쪽으로 늘리고, 아니면 새 구간을 시작합니다. 구간을 하나 처리할 때마다 <code>snap(구간, {병합됨, 현재구간, 결과수})</code> 를 남기고 <b>[병합 후 구간 수, 첫 구간의 끝, 합쳐진 구간들이 덮는 길이의 합, 병합이 일어난 횟수, 정렬을 빠뜨리고 순서대로만 훑었을 때 덮는 길이의 합]</b> 를 돌려주세요.","src":"const INTERVALS = [[1, 3], [2, 6], [8, 10], [15, 18], [9, 12]];\n\nfunction merge(list) {\n  return list;\n}\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"세 구간으로 합쳐진다","js":"RESULT[0]===3"},{"d":"첫 구간은 1~6","js":"RESULT[1]===6"},{"d":"덮는 길이의 합은 12","js":"RESULT[2]===12"},{"d":"두 번 합쳐진다","js":"RESULT[3]===2"},{"d":"정렬을 빠뜨리면 구간 하나가 삼켜져 길이가 10 으로 준다","js":"RESULT[4]===10"},{"d":"다섯 구간이 장면으로 남는다","js":"FRAMES.length===5"},{"d":"결과 수는 줄어들지 않는다","js":"FRAMES.every(function(f,i){return i===0||f.value.결과수>=FRAMES[i-1].value.결과수;})"}],"ex":"구간 병합은 <b>정렬이 알고리즘의 절반</b>인 대표적인 문제입니다. 시작점 순으로 세워 두면 '<b>다음 것이 지금 것과 겹치는가</b>' 만 보면 되므로 한 번 훑는 것으로 끝나지만(O(n log n) 은 정렬 몫), 정렬하지 않으면 더 고약합니다 — 여기서는 <b>구간 수가 3개로 똑같이 나오는데</b> 마지막 <code>[9,12]</code> 가 엉뚱하게 <code>[15,18]</code> 에 삼켜져 <b>덮는 길이만 12 에서 10 으로 줄어듭니다</b>. 개수만 확인하는 테스트로는 <b>절대 잡히지 않는</b> 종류의 버그입니다. 실무에서 이 패턴이 나오는 곳은 생각보다 많습니다: <b>회의실 예약 충돌 검사</b>, <b>장애 구간을 합쳐 실제 다운타임 계산</b>, <b>캘린더의 빈 시간 찾기</b>, <b>로그에서 연속된 오류 구간 묶기</b>, <b>IP 대역·버전 범위 정리</b>. 경계 처리는 <b>도메인이 정합니다</b> — <code>[1,3]</code> 과 <code>[3,5]</code> 를 합칠지는 '끝점을 포함하는가' 에 달렸고, 회의실이라면 3시에 끝나고 3시에 시작하는 것은 <b>겹치지 않습니다</b>. 그래서 이런 코드에는 <b>경계가 딱 맞닿는 테스트</b>를 반드시 넣으세요."},{"t":"sim","k":"문자열 시뮬레이션","lv":4,"cat":"internals","q":"쉼표가 들어 있는 CSV 한 줄을 <b>제대로</b> 나누세요. 규칙 — 큰따옴표 안의 쉼표는 <b>구분자가 아니고</b>, 큰따옴표 안에서 <code>\"\"</code> 는 <b>따옴표 한 글자</b>를 뜻합니다. 한 글자씩 읽으며 <b>따옴표 안인지</b>를 상태로 들고 다니세요. 필드를 하나 완성할 때마다 <code>snap(\"필드 \"+n, {값, 길이})</code> 를 남기고 <b>[제대로 나눈 필드 수, <code>split(',')</code> 로 나눴을 때의 필드 수, 두 번째 필드의 값, 네 번째 필드의 값, 빈 필드의 개수]</b> 를 돌려주세요.","src":"const LINE = 'a,\"b,c\",,\"d\"\"e\",f';\n\nfunction parse(line) {\n  return line.split(',');\n}\n\nfunction scene() {\n  return [0, 0, '', '', 0];\n}\n\nRESULT = scene();","tests":[{"d":"제대로 나누면 다섯 필드","js":"RESULT[0]===5"},{"d":"그냥 split 하면 여섯 개로 쪼개진다","js":"RESULT[1]===6"},{"d":"두 번째 필드 안에 쉼표가 살아 있다","js":"RESULT[2]==='b,c'"},{"d":"\"\" 는 따옴표 한 글자가 된다","js":"RESULT[3]==='d\"e'"},{"d":"빈 필드가 하나 있다","js":"RESULT[4]===1"},{"d":"다섯 필드가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"따옴표 필드는 바깥 따옴표가 벗겨진다","js":"FRAMES[1].value.값.indexOf('\"')<0"}],"ex":"<code>line.split(',')</code> 은 <b>CSV 파서가 아닙니다</b> — 데이터에 쉼표가 하나도 없을 때만 우연히 맞는 코드입니다. 실제 CSV 는 <b>따옴표 안인지 밖인지</b> 라는 상태를 들고 한 글자씩 읽어야 하고(작은 상태 기계), 여기에 <b>따옴표 안의 <code>\"\"</code> 이스케이프</b>, <b>따옴표 안의 줄바꿈</b>(한 레코드가 여러 줄에 걸침), <b>BOM</b>, <b>CRLF</b>, <b>구분자가 세미콜론인 지역 설정</b>까지 붙습니다. 그래서 실무 규칙은 하나예요 — <b>직접 짜지 말고 검증된 라이브러리를 쓰세요</b>. 그럼에도 이 문제를 손으로 풀어 볼 값어치가 있는 이유는, '<b>구분자가 데이터 안에 나타날 수 있다</b>' 는 문제가 CSV 밖에서도 반복되기 때문입니다: <b>로그를 공백으로 자르다 메시지 안의 공백에 깨지고</b>, <b>URL 쿼리를 <code>&amp;</code> 로 자르다 값 안의 <code>&amp;</code> 에 깨지고</b>, <b>SQL 을 문자열로 이어 붙이다 따옴표에 깨집니다</b>(이건 보안 사고가 됩니다). 형식이 있는 것은 <b>그 형식의 파서로</b> 다루는 것이 답입니다."},{"t":"sim","k":"재귀 시뮬레이션","lv":3,"cat":"internals","q":"같은 재귀를 <b>기억하며 푸는 것</b>과 아닌 것의 호출 수를 세세요. <code>fib(n) = fib(n−1) + fib(n−2)</code>, <code>fib(0)=0</code>, <code>fib(1)=1</code> 입니다. 두 방식 모두 <b>함수에 들어갈 때마다 1 을 세고</b>, 메모 방식은 <b>이미 계산해 둔 값을 만나면 적중으로 세고 바로 돌려줍니다</b>. n = 5·10·20 을 각각 돌리며 <code>snap(\"fib(\"+n+\")\", {메모없이, 메모, 적중})</code> 을 남기고 <b>[n=20 에서 메모 없는 호출 수, 메모를 쓴 호출 수, 몇 배 줄었나(정수), 메모 적중 횟수, fib(20) 의 값]</b> 을 돌려주세요.","src":"const NS = [5, 10, 20];\n\nfunction naive(n) {\n  return 0;\n}\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"메모 없이는 21,891번 부른다","js":"RESULT[0]===21891"},{"d":"메모를 쓰면 39번","js":"RESULT[1]===39"},{"d":"561배 줄었다","js":"RESULT[2]===561"},{"d":"18번은 이미 계산한 값을 꺼내 썼다","js":"RESULT[3]===18"},{"d":"fib(20) 은 6765","js":"RESULT[4]===6765"},{"d":"세 크기가 장면으로 남는다","js":"FRAMES.length===3"},{"d":"n 이 커질수록 격차가 벌어진다","js":"FRAMES[2].value.메모없이/FRAMES[2].value.메모 > FRAMES[0].value.메모없이/FRAMES[0].value.메모"}],"ex":"재귀 피보나치가 느린 이유는 <b>같은 값을 몇 번이고 다시 계산</b>하기 때문입니다 — <code>fib(20)</code> 을 구하는 동안 <code>fib(5)</code> 만 해도 수백 번 계산됩니다. 호출 수는 <b>지수(약 2ⁿ)</b> 로 늘어 n=20 에 2만 번, n=40 이면 <b>수십억 번</b>이 됩니다. 이미 구한 답을 표에 적어 두기만 하면(<b>메모이제이션</b>) 각 n 은 <b>딱 한 번씩만</b> 계산되어 <b>O(n)</b> 이 됩니다 — 여기서는 21,891 이 39 로, 561배 줄었습니다. 이 기법이 통하는 조건은 둘입니다: <b>같은 입력에 늘 같은 결과</b>(순수 함수)이고, <b>부분 문제가 겹칠 것</b>. 겹치지 않으면(예: 이진 탐색) 메모는 <b>메모리만 먹습니다</b>. 실무에서 주의할 점도 있습니다 — 메모 표는 <b>계속 자라므로</b> 오래 사는 프로세스에서는 <b>크기 상한이나 LRU</b>가 필요하고, <b>인자가 객체면 키를 어떻게 만들지</b>(JSON 문자열? 참조?)가 정확성을 좌우합니다. 그리고 재귀 깊이가 문제라면 아예 <b>아래에서 위로 표를 채우는 반복문</b>(타뷸레이션)으로 바꾸면 스택도 쓰지 않습니다."},{"t":"sim","k":"변환 시뮬레이션","lv":3,"cat":"internals","q":"겹겹이 쌓인 배열을 <b>몇 겹까지 펴느냐</b>에 따라 결과가 어떻게 달라지는지 보세요. <code>flat(d)</code> 는 <b>d 겹만</b> 펴고, <code>flat(Infinity)</code> 는 끝까지 폅니다. 깊이 0·1·2·∞ 로 각각 펴 보며 <code>snap(\"flat(\"+d+\")\", {길이, 아직배열인원소})</code> 를 남기고 <b>[flat(1) 뒤 길이, flat(2) 뒤 길이, flat(Infinity) 뒤 길이, 원본의 최대 중첩 깊이, 원본에 <code>flatMap(x =&gt; [x, x])</code> 를 적용한 결과의 길이]</b> 를 돌려주세요.","src":"const NESTED = [1, [2, [3, [4, [5]]]], 6];\nconst DEPTHS = [0, 1, 2, Infinity];\n\nfunction maxDepth(a) {\n  return 0;\n}\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"한 겹만 펴면 길이 4","js":"RESULT[0]===4"},{"d":"두 겹이면 5","js":"RESULT[1]===5"},{"d":"끝까지 펴면 6","js":"RESULT[2]===6"},{"d":"원본은 다섯 겹까지 들어가 있다","js":"RESULT[3]===5"},{"d":"flatMap 은 한 겹만 펴므로 길이 6","js":"RESULT[4]===6"},{"d":"네 깊이가 장면으로 남는다","js":"FRAMES.length===4"},{"d":"끝까지 펴야 배열이 남지 않는다","js":"FRAMES[3].value.아직배열인원소===0 && FRAMES[1].value.아직배열인원소>0"}],"ex":"<code>flat()</code> 의 기본 깊이가 <b>1</b> 이라는 것이 가장 흔한 함정입니다 — 두 겹 이상 중첩된 데이터에 그냥 <code>flat()</code> 을 부르면 <b>안쪽 배열이 그대로 남아</b>, 그 뒤의 <code>map</code> 이나 비교가 조용히 이상해집니다. 깊이를 모르면 <code>flat(Infinity)</code> 를 쓰면 되지만, <b>정말 끝까지 펴는 게 맞는지</b>는 데이터 모양에 달렸습니다 — 의미가 있는 중첩(행렬의 행, 그룹)을 무심코 펴 버리면 구조가 사라집니다. <code>flatMap</code> 도 함께 기억해 두세요: <b><code>map</code> 한 결과를 한 겹만 펴 주는</b> 것이라 <b>'하나를 0개 또는 여러 개로 바꾸는'</b> 변환에 딱 맞습니다 — 빈 배열을 돌려주면 <b>그 원소를 걸러내는 효과</b>가 나서 <code>filter</code> 와 <code>map</code> 을 한 번에 하는 관용구로 쓰입니다(<code>xs.flatMap(x =&gt; ok(x) ? [f(x)] : [])</code>). 다만 이름과 달리 <b>깊이 인자를 받지 않으므로</b>, 여러 겹이 필요하면 <code>map</code> 뒤에 <code>flat(n)</code> 을 따로 쓰세요."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]}]);
